const COURSE={"lessons":[{"id":"lesson-1","title":"Course Intro","day":0,"section":0,"url":"https://www.loom.com/share/c7d3a6508ce346299ab627d3466d2319","embed":"https://www.loom.com/embed/c7d3a6508ce346299ab627d3466d2319","questions":[{"stem":"A problem asks for 3x + 2, where x is the positive solution of x² − 5x − 14 = 0. Which plan directly answers the question?","choices":["Find both roots, use the positive root, then evaluate 3x + 2.","Read the y-intercept of the quadratic.","Use the smaller root because it appears first.","Report the positive root without another calculation."],"answer":"A","why":"The roots are −2 and 7. The positive-root condition selects 7, and the requested expression is 23. Identify both the restriction and the target before entering anything.","math":null,"figure":null,"id":"lesson-1-q1","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"A graphing window shows no intersection of y = 0.02x + 12 and y = 0.03x + 2. Which next step is justified?","choices":["Conclude that the system has no solution.","Expand the window or solve the equations algebraically.","Change a coefficient until an intersection appears.","Round both slopes to zero."],"answer":"B","why":"Different slopes ensure one intersection. Solving gives x = 1,000 and y = 32, outside a typical initial window. A missing visible point is not proof of no solution.","math":null,"figure":null,"id":"lesson-1-q2","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"A student finds that two expressions have the same value at x = 0 and concludes they are equivalent for every x. What would best strengthen the work?","choices":["Check that both expressions have a y-intercept.","Use another screenshot of the same point.","Simplify the difference algebraically and check the domains.","Change every variable to zero."],"answer":"C","why":"One matching value cannot establish an identity. For example, x and x² agree at zero but differ at two. An algebraic identity with matching domains establishes equivalence.","math":null,"figure":null,"id":"lesson-1-q3","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"A system of three equations has a point that satisfies the first two equations. What must the student do before accepting that point?","choices":["Confirm that it also satisfies the third equation.","Find the average of the three y-intercepts.","Discard the third equation.","Choose the intersection with the greatest x-coordinate."],"answer":"A","why":"A solution of a system must satisfy every equation simultaneously. This targets the common-intersection error from your PSAT.","math":null,"figure":null,"id":"lesson-1-q4","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"After a wrong answer, which review note would be most useful for preventing the same mistake?","choices":["I need to be more careful.","I forgot to test whether the boundary was included; next time I will check < versus ≤ before choosing a point.","This question was unfair.","I should memorize this question’s answer."],"answer":"B","why":"The useful note names the missed condition and gives a specific future action. Apply that action to a different problem to check transfer.","math":null,"figure":null,"id":"lesson-1-q5","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"}]},{"id":"lesson-2","title":"Desmos Intro","day":0,"section":0,"url":"https://www.loom.com/share/933c2689261045a78ae22505fd44c863","embed":"https://www.loom.com/embed/933c2689261045a78ae22505fd44c863","questions":[{"stem":"A quadratic is shown below. What is its minimum value?","choices":null,"answer":"-9","why":"Complete the square: (x − 4)² − 9. The vertex is (4, −9); the minimum is the y-coordinate, not the x-coordinate.","math":"f(x)=x^2-8x+7","figure":null,"id":"lesson-2-q1","equations":["assets/lesson-2-q1-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"The table lists the number of pages read on five days: 12, 18, 18, 25, and 42. What is the median?","choices":null,"answer":"18","why":"The list is ordered and has five entries. The third entry, 18, is the median. The mean is 23 and answers a different question.","math":null,"figure":null,"id":"lesson-2-q2","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"For the function below, what is f(−3)?","choices":null,"answer":"14","why":"Use parentheses around the negative input: 2(−3)² + (−3) − 1 = 18 − 3 − 1 = 14.","math":"f(x)=2x^2+x-1","figure":null,"id":"lesson-2-q3","equations":["assets/lesson-2-q3-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"An angle measures 150°. What is its sine?","choices":["−√3/2","−1/2","1/2","√3/2"],"answer":"C","why":"Use degree mode for the stated degree measure. The reference angle is 30° and sine is positive in quadrant II, so the value is 1/2.","math":"\\sin(150^\\circ)","figure":null,"id":"lesson-2-q4","equations":["assets/lesson-2-q4-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Points A(−5, 2) and B(7, 10) are the endpoints of a segment. What is the y-coordinate of its midpoint?","choices":null,"answer":"6","why":"Average corresponding coordinates: ((−5 + 7)/2, (2 + 10)/2) = (1, 6).","math":null,"figure":null,"id":"lesson-2-q5","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"A jacket costing $80 is discounted by 15%, then a 6% sales tax is applied to the discounted price. What is the final price, in dollars?","choices":null,"answer":"72.08","why":"The discounted price is 80(0.85) = 68. The final price is 68(1.06) = 72.08. The tax applies to the discounted price.","math":null,"figure":null,"id":"lesson-2-q6","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"A function is defined only for 1 ≤ x < 5. Which point belongs to its graph?","choices":["(0, 1)","(1, 4)","(5, 16)","(6, 19)"],"answer":"B","why":"The rule gives y = 3x + 1, so (1, 4) satisfies it and includes the left endpoint. The right endpoint x = 5 is excluded.","math":"f(x)=3x+1\\quad(1\\leq x<5)","figure":null,"id":"lesson-2-q7","equations":["assets/lesson-2-q7-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"}]},{"id":"lesson-3","title":"Single Variable Equations","day":1,"section":0,"url":"https://www.loom.com/share/95a61ed1e55b469390eade41a43304b9","embed":"https://www.loom.com/embed/95a61ed1e55b469390eade41a43304b9","questions":[{"stem":"What is the greater solution of the equation below?","choices":null,"answer":"8","why":"The quadratic factors as (x − 8)(x + 3) = 0, giving −3 and 8.","math":"x^2-5x-24=0","figure":null,"id":"lesson-3-q1","equations":["assets/lesson-3-q1-0.png"],"difficulty":"Hard","hardFocus":"Radicals, rational restrictions, parameter conditions, and target expressions"},{"stem":"If x is the positive solution of the equation below, what is x/4?","choices":null,"answer":"3","why":"The solutions are x = 12 and x = −6. Use the positive solution and report 12/4 = 3.","math":"|x-3|=9","figure":null,"id":"lesson-3-q2","equations":["assets/lesson-3-q2-0.png"],"difficulty":"Hard","hardFocus":"Radicals, rational restrictions, parameter conditions, and target expressions"},{"stem":"The equation below has one solution in its domain. What is it?","choices":null,"answer":"9","why":"Multiply by x − 2, which cannot be zero: 3x + 1 = 4x − 8. Thus x = 9, which is permitted.","math":"\\frac{3x+1}{x-2}=4","figure":null,"id":"lesson-3-q3","equations":["assets/lesson-3-q3-0.png"],"difficulty":"Hard","hardFocus":"Radicals, rational restrictions, parameter conditions, and target expressions"},{"stem":"Which value solves the equation below?","choices":["−1","0","4","9"],"answer":"C","why":"Squaring gives x + 5 = (x − 1)², so x = −1 or 4. The original right side must be nonnegative; −1 is extraneous. At x = 4 both sides equal 3.","math":"\\sqrt{x+5}=x-1","figure":null,"id":"lesson-3-q4","equations":["assets/lesson-3-q4-0.png"],"difficulty":"Hard","hardFocus":"Radicals, rational restrictions, parameter conditions, and target expressions"},{"stem":"A quantity is modeled by the expression below. At what value of t does the quantity equal 54?","choices":null,"answer":"2","why":"Divide by 6 to obtain 3ᵗ = 9, so t = 2.","math":"Q(t)=6(3)^t","figure":null,"id":"lesson-3-q5","equations":["assets/lesson-3-q5-0.png"],"difficulty":"Hard","hardFocus":"Radicals, rational restrictions, parameter conditions, and target expressions"},{"stem":"The smaller root of x² − 10x + k = 0 is 4. What is k?","choices":null,"answer":"24","why":"Substitute 4: 16 − 40 + k = 0, so k = 24. The other root is 6, confirming that 4 is smaller.","math":null,"figure":null,"id":"lesson-3-q6","equations":[],"difficulty":"Hard","hardFocus":"Radicals, rational restrictions, parameter conditions, and target expressions"},{"stem":"The equation below has a solution x. What is x + 1?","choices":null,"answer":"9","why":"Multiply by (x − 2)(x + 1), excluding 2 and −1: 2(x + 1) = 3(x − 2). Thus x = 8, and x + 1 = 9.","math":"\\frac{2}{x-2}=\\frac{3}{x+1}","figure":null,"id":"lesson-3-q7","equations":["assets/lesson-3-q7-0.png"],"difficulty":"Hard","hardFocus":"Radicals, rational restrictions, parameter conditions, and target expressions"}]},{"id":"lesson-4","title":"Systems of Equations","day":1,"section":0,"url":"https://www.loom.com/share/8dd69026ee434e149e86aa04a471bcb2","embed":"https://www.loom.com/embed/8dd69026ee434e149e86aa04a471bcb2","questions":[{"stem":"What is the value of x + y for the system below?","choices":null,"answer":"8","why":"The first equation gives x = 11 − 2y. Substitution yields 3(11 − 2y) − y = 12, so y = 3 and x = 5. Therefore x + y = 8.","math":"\\begin{gathered}x+2y=11\\\\3x-y=12\\end{gathered}","figure":null,"id":"lesson-4-q1","equations":["assets/lesson-4-q1-0.png","assets/lesson-4-q1-1.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"The three equations below have a common solution (x, y). What is k?","choices":null,"answer":"14","why":"The first two equations give x = 4 and y = 3. Substituting into the third gives k = 2(4) + 2(3) = 14.","math":"\\begin{gathered}x+y=7\\\\x-y=1\\\\2x+2y=k\\end{gathered}","figure":null,"id":"lesson-4-q2","equations":["assets/lesson-4-q2-0.png","assets/lesson-4-q2-1.png","assets/lesson-4-q2-2.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"Which point is a solution of all three equations?","choices":["(2, 3)","(3, 2)","(1, 4)","(4, 1)"],"answer":"A","why":"Every option has x + y = 5. Only (2, 3) also has 2x − y = 1 and xy = 6. Checking just one or two equations is insufficient.","math":"\\begin{gathered}x+y=5\\\\2x-y=1\\\\xy=6\\end{gathered}","figure":null,"id":"lesson-4-q3","equations":["assets/lesson-4-q3-0.png","assets/lesson-4-q3-1.png","assets/lesson-4-q3-2.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"For every real solution of the system below, what is x² + y²?","choices":null,"answer":"29","why":"Expand (x + y)² = x² + 2xy + y². Therefore x² + y² = 49 − 20 = 29. Either ordered solution gives the same value.","math":"\\begin{gathered}x+y=7\\\\xy=10\\end{gathered}","figure":null,"id":"lesson-4-q4","equations":["assets/lesson-4-q4-0.png","assets/lesson-4-q4-1.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"The line y = 2x + 1 intersects the parabola y = x² − 2x + 1 at two points. What is the larger x-coordinate?","choices":null,"answer":"4","why":"Set the expressions equal: x² − 4x = 0. The x-coordinates are 0 and 4.","math":null,"figure":null,"id":"lesson-4-q5","equations":[],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"A system has the unique solution shown by the equations below. What is y?","choices":null,"answer":"4","why":"Substitution gives 2(3y − 5) + y = 18, so 7y = 28 and y = 4.","math":"\\begin{gathered}x=3y-5\\\\2x+y=18\\end{gathered}","figure":null,"id":"lesson-4-q6","equations":["assets/lesson-4-q6-0.png","assets/lesson-4-q6-1.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"What is the solution set of the three equations below?","choices":["Only (3, 2)","Only (2, 3)","Infinitely many points","No solution"],"answer":"D","why":"The first two require x = 3 and y = 2. At that point 3x + y = 11, not 12, so the three equations have no common solution.","math":"\\begin{gathered}x+y=5\\\\x-y=1\\\\3x+y=12\\end{gathered}","figure":null,"id":"lesson-4-q7","equations":["assets/lesson-4-q7-0.png","assets/lesson-4-q7-1.png","assets/lesson-4-q7-2.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"If x and y satisfy the equations below, what is 2ˣ/4ʸ?","choices":null,"answer":"8","why":"Rewrite 4ʸ as 2²ʸ. The ratio is 2^(x − 2y) = 2³ = 8. You do not need the individual values.","math":"\\begin{gathered}x-2y=3\\\\x+y=12\\end{gathered}","figure":null,"id":"lesson-4-q8","equations":["assets/lesson-4-q8-0.png","assets/lesson-4-q8-1.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"The system below has two real solutions. What is the sum of their x-coordinates?","choices":null,"answer":"5","why":"Substitute y = 5 − x into xy = 4 to get x² − 5x + 4 = 0. Its roots are 1 and 4, whose sum is 5.","math":"\\begin{gathered}x+y=5\\\\xy=4\\end{gathered}","figure":null,"id":"lesson-4-q9","equations":["assets/lesson-4-q9-0.png","assets/lesson-4-q9-1.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"},{"stem":"The equations below have a common solution. What is c?","choices":null,"answer":"13","why":"The first two imply y = 3x − 4 and y = −x + 8. Thus x = 3, y = 5, and c = x + 2y = 13.","math":"\\begin{gathered}3x-y=4\\\\x+y=8\\\\x+2y=c\\end{gathered}","figure":null,"id":"lesson-4-q10","equations":["assets/lesson-4-q10-0.png","assets/lesson-4-q10-1.png","assets/lesson-4-q10-2.png"],"difficulty":"Hard","hardFocus":"Multiple conditions, hidden parameters, and common-solution checks"}]},{"id":"lesson-5","title":"Number of Solutions","day":1,"section":0,"url":"https://www.loom.com/share/e4065e889131497da2514d6208f3f3ec","embed":"https://www.loom.com/embed/e4065e889131497da2514d6208f3f3ec","questions":[{"stem":"How many real solutions does the equation below have?","choices":["0","1","2","Infinitely many"],"answer":"B","why":"The equation becomes (x − 3)² = 0. A repeated root is one distinct real solution.","math":"x^2-6x+9=0","figure":null,"id":"lesson-5-q1","equations":["assets/lesson-5-q1-0.png"],"difficulty":"Hard","hardFocus":"Discriminants, domains, repeated roots, and extraneous solutions"},{"stem":"How many real solutions does the equation below have?","choices":["0","1","2","Infinitely many"],"answer":"A","why":"The left side is at least 4 for every real x, so it cannot equal zero.","math":"(x+2)^2+4=0","figure":null,"id":"lesson-5-q2","equations":["assets/lesson-5-q2-0.png"],"difficulty":"Hard","hardFocus":"Discriminants, domains, repeated roots, and extraneous solutions"},{"stem":"How many solutions does the system below have?","choices":["0","1","2","Infinitely many"],"answer":"D","why":"Dividing the second equation by 3 gives the first. They represent the same line, so every point on that line solves both.","math":"\\begin{gathered}2x-3y=6\\\\6x-9y=18\\end{gathered}","figure":null,"id":"lesson-5-q3","equations":["assets/lesson-5-q3-0.png","assets/lesson-5-q3-1.png"],"difficulty":"Hard","hardFocus":"Discriminants, domains, repeated roots, and extraneous solutions"},{"stem":"How many solutions does the system below have?","choices":["0","1","2","Infinitely many"],"answer":"A","why":"The second equation reduces to 2x − 3y = 7, which contradicts 2x − 3y = 6. These are parallel distinct lines.","math":"\\begin{gathered}2x-3y=6\\\\4x-6y=14\\end{gathered}","figure":null,"id":"lesson-5-q4","equations":["assets/lesson-5-q4-0.png","assets/lesson-5-q4-1.png"],"difficulty":"Hard","hardFocus":"Discriminants, domains, repeated roots, and extraneous solutions"},{"stem":"For what value of k does y = x² − 4x + 7 and y = k have exactly one common point?","choices":null,"answer":"3","why":"The parabola is (x − 2)² + 3. A horizontal line touches it once only at the vertex height, k = 3.","math":null,"figure":null,"id":"lesson-5-q5","equations":[],"difficulty":"Hard","hardFocus":"Discriminants, domains, repeated roots, and extraneous solutions"},{"stem":"How many real solutions does the equation below have?","choices":["0","1","2","3"],"answer":"C","why":"Split at x = 2. For x ≥ 2, x − 2 = x/2 + 1 gives x = 6. For x < 2, 2 − x = x/2 + 1 gives x = 2/3. Both satisfy their cases.","math":"|x-2|=\\frac{x}{2}+1","figure":null,"id":"lesson-5-q6","equations":["assets/lesson-5-q6-0.png"],"difficulty":"Hard","hardFocus":"Discriminants, domains, repeated roots, and extraneous solutions"},{"stem":"How many real solutions does the equation below have?","choices":["0","1","2","Infinitely many"],"answer":"D","why":"Each side expands to 3x + 6. This is an identity, so every real x is a solution. A graph display alone may not distinguish an identity from an inconsistent equation.","math":"3(x+2)=3x+6","figure":null,"id":"lesson-5-q7","equations":["assets/lesson-5-q7-0.png"],"difficulty":"Hard","hardFocus":"Discriminants, domains, repeated roots, and extraneous solutions"}]},{"id":"lesson-6","title":"Equivalent Expressions","day":2,"section":0,"url":"https://www.loom.com/share/b9fb1b2fecae4063b7c363347371a58e","embed":"https://www.loom.com/embed/b9fb1b2fecae4063b7c363347371a58e","questions":[{"stem":"Which expression is equivalent to the expression below for every real x?","choices":["2x² + 3x − 2","2x² − 3x − 2","2x² + 5x − 2","2x² − x + 2"],"answer":"A","why":"Multiply each term: 2x² + 4x − x − 2 = 2x² + 3x − 2.","math":"(2x-1)(x+2)","figure":null,"id":"lesson-6-q1","equations":["assets/lesson-6-q1-0.png"],"difficulty":"Hard","hardFocus":"Parameter identities, factoring, domains, and coefficient matching"},{"stem":"For x ≠ 3, which expression is equivalent to the expression below?","choices":["x + 3","x − 3","x² + 3","1"],"answer":"A","why":"Factor the numerator as (x − 3)(x + 3), then cancel x − 3 only on the permitted domain. The original expression remains undefined at x = 3.","math":"\\frac{x^2-9}{x-3}","figure":null,"id":"lesson-6-q2","equations":["assets/lesson-6-q2-0.png"],"difficulty":"Hard","hardFocus":"Parameter identities, factoring, domains, and coefficient matching"},{"stem":"Which expression equals the expression below for all real a and b?","choices":["a² + b²","a² + 2ab + b²","a² + 3ab + b²","a² − ab + b²"],"answer":"B","why":"Expanding (a − b)² gives a² − 2ab + b²; adding 4ab gives a² + 2ab + b².","math":"(a-b)^2+4ab","figure":null,"id":"lesson-6-q3","equations":["assets/lesson-6-q3-0.png"],"difficulty":"Hard","hardFocus":"Parameter identities, factoring, domains, and coefficient matching"},{"stem":"The identity below holds for all real x. What is k?","choices":null,"answer":"10","why":"Expand the left side to x² + 10x + 25. Match the x-coefficient, k = 10.","math":"(x+5)^2=x^2+kx+25","figure":null,"id":"lesson-6-q4","equations":["assets/lesson-6-q4-0.png"],"difficulty":"Hard","hardFocus":"Parameter identities, factoring, domains, and coefficient matching"},{"stem":"Which expression is equivalent to the expression below when t > 0?","choices":["t²","t³","t⁴","t⁸"],"answer":"C","why":"Multiply exponents first: (t^(3/2))⁴ = t⁶. Divide by t² to obtain t⁴.","math":"\\frac{(t^{3/2})^4}{t^2}","figure":null,"id":"lesson-6-q5","equations":["assets/lesson-6-q5-0.png"],"difficulty":"Hard","hardFocus":"Parameter identities, factoring, domains, and coefficient matching"},{"stem":"A student compares (x + a)² and x² + a² using a = 0 and sees matching graphs. Which statement is correct?","choices":["They are equivalent for every a.","Their difference is 2ax, so the special test hides the difference.","They can never be equal.","Replacing x with a proves equivalence."],"answer":"B","why":"The missing cross term is 2ax. It vanishes when a = 0, so that parameter choice provides misleading evidence.","math":null,"figure":null,"id":"lesson-6-q6","equations":[],"difficulty":"Hard","hardFocus":"Parameter identities, factoring, domains, and coefficient matching"},{"stem":"For x ≠ 0, the expression below equals ax + b. What is a + b?","choices":null,"answer":"7","why":"Divide each numerator term by x: 3x + 4. Thus a = 3, b = 4, and a + b = 7.","math":"\\frac{3x^2+4x}{x}","figure":null,"id":"lesson-6-q7","equations":["assets/lesson-6-q7-0.png"],"difficulty":"Hard","hardFocus":"Parameter identities, factoring, domains, and coefficient matching"}]},{"id":"lesson-7","title":"Deeper Dive into Functions","day":2,"section":0,"url":"https://www.loom.com/share/2394c5e0ef014f4796801663289bd28e","embed":"https://www.loom.com/embed/2394c5e0ef014f4796801663289bd28e","questions":[{"stem":"For the functions below, what is f(g(2))?","choices":null,"answer":"13","why":"First g(2) = 3. Then f(3) = 3² + 4 = 13. Reversing the composition gives a different result.","math":"f(x)=x^2+4,\\quad g(x)=2x-1","figure":null,"id":"lesson-7-q1","equations":["assets/lesson-7-q1-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"If f(x) = 3x − 7, what input t satisfies f(t) = 20?","choices":null,"answer":"9","why":"Solve 3t − 7 = 20, so t = 9.","math":null,"figure":null,"id":"lesson-7-q2","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"The graph of g is the graph of f shifted 4 units left and 2 units up. Which equation defines g?","choices":["g(x) = f(x − 4) + 2","g(x) = f(x + 4) + 2","g(x) = f(x + 2) + 4","g(x) = f(x + 4) − 2"],"answer":"B","why":"Replacing x by x + 4 shifts the graph left 4; adding 2 shifts it up 2.","math":null,"figure":null,"id":"lesson-7-q3","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"If f(x) = x² − 2x, what is f(−3)?","choices":null,"answer":"15","why":"Substitute the entire input: (−3)² − 2(−3) = 9 + 6 = 15.","math":null,"figure":null,"id":"lesson-7-q4","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"If f(x) = 2x + 5 and g(x) = x², which expression equals g(f(x))?","choices":["2x² + 5","4x² + 25","4x² + 20x + 25","2x² + 20x + 5"],"answer":"C","why":"g squares its complete input: (2x + 5)² = 4x² + 20x + 25.","math":null,"figure":null,"id":"lesson-7-q5","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"The function below has zeros at −2 and 6. What is f(2)?","choices":null,"answer":"-16","why":"At x = 2, the factors are 4 and −4, so their product is −16.","math":"f(x)=(x+2)(x-6)","figure":null,"id":"lesson-7-q6","equations":["assets/lesson-7-q6-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"For the function below, what is the greatest value of f on its stated domain?","choices":null,"answer":"9","why":"The unrestricted maximum is 10 at x = 4, outside the domain. On 0 ≤ x ≤ 3 the function increases; f(3) = 9 is the greatest permitted value.","math":"f(x)=10-(x-4)^2,\\quad 0\\leq x\\leq3","figure":null,"id":"lesson-7-q7","equations":["assets/lesson-7-q7-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"}]},{"id":"lesson-8","title":"Inequalities","day":3,"section":0,"url":"https://www.loom.com/share/a33846ce38224281be7d992f8511bcb4","embed":"https://www.loom.com/embed/a33846ce38224281be7d992f8511bcb4","questions":[{"stem":"Which point satisfies both inequalities below?","choices":["(2, 5)","(2, 4)","(3, 7)","(1, 4)"],"answer":"B","why":"At (2, 4), 4 < 5 and 4 ≥ 4. A lies on the excluded first boundary, C fails the first inequality, and D fails it as well.","math":"\\begin{gathered}y<2x+1\\\\y\\geq x+2\\end{gathered}","figure":null,"id":"lesson-8-q1","equations":["assets/lesson-8-q1-0.png","assets/lesson-8-q1-1.png"],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"If x = 4, what is the greatest integer y satisfying both inequalities?","choices":null,"answer":"8","why":"The inequalities become y < 9 and y ≥ 6. The greatest integer is 8.","math":"\\begin{gathered}y<3x-3\\\\y\\geq x+2\\end{gathered}","figure":null,"id":"lesson-8-q2","equations":["assets/lesson-8-q2-0.png","assets/lesson-8-q2-1.png"],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"Which interval describes all real x satisfying the inequality below?","choices":["x < −3","x > −3","x < 3","x > 3"],"answer":"B","why":"Subtract 5: −2x < 6. Divide by −2 and reverse the inequality to obtain x > −3.","math":"5-2x<11","figure":null,"id":"lesson-8-q3","equations":["assets/lesson-8-q3-0.png"],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"Which pair describes all solutions of the inequalities below?","choices":["x ≥ 3 and x < 7","x > 3 and x ≤ 7","x ≥ 3 and x ≤ 7","x ≤ 3 or x ≥ 7"],"answer":"A","why":"The first gives x ≥ 3. The second gives x < 7. Both must hold, including 3 and excluding 7.","math":"\\begin{gathered}2x+1\\geq7\\\\3x-2<19\\end{gathered}","figure":null,"id":"lesson-8-q4","equations":["assets/lesson-8-q4-0.png","assets/lesson-8-q4-1.png"],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"Tickets cost $12 each, and a $9 booking fee is charged once. With a budget of at most $100, what is the greatest number of tickets that can be bought?","choices":null,"answer":"7","why":"12n + 9 ≤ 100 gives n ≤ 91/12 ≈ 7.58. The ticket count must be an integer, so at most 7.","math":null,"figure":null,"id":"lesson-8-q5","equations":[],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"Which graph description matches y ≥ −x + 3?","choices":["Dashed boundary; shading below","Dashed boundary; shading above","Solid boundary; shading above","Solid boundary; shading below"],"answer":"C","why":"Equality is included, so the line is solid. Greater y-values lie above the line.","math":null,"figure":null,"id":"lesson-8-q6","equations":[],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"How many integer values of x satisfy |x − 2| < 4?","choices":null,"answer":"7","why":"The inequality is −4 < x − 2 < 4, or −2 < x < 6. The integers are −1, 0, 1, 2, 3, 4, and 5.","math":null,"figure":null,"id":"lesson-8-q7","equations":[],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"Which value of x satisfies both x² < 16 and x ≥ 3?","choices":["−3","2","3","4"],"answer":"C","why":"The quadratic inequality requires −4 < x < 4. Intersecting with x ≥ 3 gives 3 ≤ x < 4. Only 3 is offered.","math":null,"figure":null,"id":"lesson-8-q8","equations":[],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"At x = 3, how many integer y-values satisfy all three inequalities below?","choices":null,"answer":"2","why":"Substitute x = 3: y > 2, y ≤ 6, and y < 5. The integers are 3 and 4.","math":"\\begin{gathered}y>x-1\\\\y\\leq2x\\\\x+y<8\\end{gathered}","figure":null,"id":"lesson-8-q9","equations":["assets/lesson-8-q9-0.png","assets/lesson-8-q9-1.png","assets/lesson-8-q9-2.png"],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"},{"stem":"The feasible region is defined below. Which point lies on an included boundary and also satisfies every inequality?","choices":["(0, 0)","(1, 5)","(2, 2)","(5, 0)"],"answer":"C","why":"At (2, 2), x + y = 4 is included, x > 0, and y < 5. The other points fail at least one condition.","math":"\\begin{gathered}x+y\\leq4\\\\x>0\\\\y<5\\end{gathered}","figure":null,"id":"lesson-8-q10","equations":["assets/lesson-8-q10-0.png","assets/lesson-8-q10-1.png","assets/lesson-8-q10-2.png"],"difficulty":"Hard","hardFocus":"Several simultaneous constraints, boundary inclusion, and feasible regions"}]},{"id":"lesson-9","title":"Circle Equations","day":3,"section":0,"url":"https://www.loom.com/share/b45f1394a000413bbfcd5624b3dbac3d","embed":"https://www.loom.com/embed/b45f1394a000413bbfcd5624b3dbac3d","questions":[{"stem":"What is the center of the circle below?","choices":["(3, −2)","(−3, 2)","(3, 2)","(−3, −2)"],"answer":"A","why":"Compare (x − h)² + (y − k)² = r². Here h = 3 and k = −2.","math":"(x-3)^2+(y+2)^2=49","figure":null,"id":"lesson-9-q1","equations":["assets/lesson-9-q1-0.png"],"difficulty":"Hard","hardFocus":"Expanded forms, constraints, and requested quantities rather than full equations"},{"stem":"What is the radius of the circle below?","choices":null,"answer":"5","why":"Divide by 2: x² − 4x + y² + 6y = 12. Complete the squares: (x − 2)² + (y + 3)² = 25. Radius = 5.","math":"2x^2-8x+2y^2+12y=24","figure":null,"id":"lesson-9-q2","equations":["assets/lesson-9-q2-0.png"],"difficulty":"Hard","hardFocus":"Expanded forms, constraints, and requested quantities rather than full equations"},{"stem":"The endpoints of a diameter are (−4, 1) and (8, 1). What is the x-coordinate of the center?","choices":null,"answer":"2","why":"The center is the midpoint: ((−4 + 8)/2, 1) = (2, 1).","math":null,"figure":null,"id":"lesson-9-q3","equations":[],"difficulty":"Hard","hardFocus":"Expanded forms, constraints, and requested quantities rather than full equations"},{"stem":"Which point lies on the circle below?","choices":["(5, 2)","(2, 4)","(1, 1)","(6, 1)"],"answer":"B","why":"The center is (2, 1) and radius 3. (2, 4) is 3 units away. The squared distances of the other points are 10, 1, and 16.","math":"(x-2)^2+(y-1)^2=9","figure":null,"id":"lesson-9-q4","equations":["assets/lesson-9-q4-0.png"],"difficulty":"Hard","hardFocus":"Expanded forms, constraints, and requested quantities rather than full equations"},{"stem":"A circle has center (−1, 4) and radius 6. What is the greatest y-coordinate of a point on the circle?","choices":null,"answer":"10","why":"The highest point is 6 units above the center: 4 + 6 = 10.","math":null,"figure":null,"id":"lesson-9-q5","equations":[],"difficulty":"Hard","hardFocus":"Expanded forms, constraints, and requested quantities rather than full equations"},{"stem":"For the circle below, which point is not in its interior?","choices":["(0, 0)","(1, 1)","(2, 0)","(1, 0)"],"answer":"C","why":"The point (2, 0) satisfies x² + y² = 4 and lies on the boundary. A point not in the interior can be on the boundary or outside.","math":"x^2+y^2=4","figure":null,"id":"lesson-9-q6","equations":["assets/lesson-9-q6-0.png"],"difficulty":"Hard","hardFocus":"Expanded forms, constraints, and requested quantities rather than full equations"},{"stem":"The circle below has radius r. What is r²?","choices":null,"answer":"20","why":"Complete the squares: (x + 3)² + (y − 2)² = 7 + 9 + 4 = 20. The question asks for r², so do not take the square root.","math":"x^2+6x+y^2-4y=7","figure":null,"id":"lesson-9-q7","equations":["assets/lesson-9-q7-0.png"],"difficulty":"Hard","hardFocus":"Expanded forms, constraints, and requested quantities rather than full equations"}]},{"id":"lesson-10","title":"Regression Part 1","day":4,"section":0,"url":"https://www.loom.com/share/c8831fda2ec44e2490ed507d4762c5df","embed":"https://www.loom.com/embed/c8831fda2ec44e2490ed507d4762c5df","questions":[{"stem":"A linear function passes through (2, 11) and (6, 23). What is its y-intercept?","choices":null,"answer":"5","why":"The slope is (23 − 11)/(6 − 2) = 3. In y = 3x + b, the point (2, 11) gives b = 5.","math":null,"figure":null,"id":"lesson-10-q1","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Linear model from two points"},{"stem":"An exponential model f(x) = abˣ, with a > 0 and b > 0, satisfies f(1) = 12 and f(3) = 108. What is b?","choices":null,"answer":"3","why":"Divide the values: b² = 108/12 = 9. Since b > 0, b = 3. Then a = 4; verify both original points.","math":null,"figure":null,"id":"lesson-10-q2","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Exponential model from separated inputs"},{"stem":"A quadratic has vertex (3, −5) and passes through (5, 7). What is its leading coefficient?","choices":null,"answer":"3","why":"Use f(x) = a(x − 3)² − 5. Substituting (5, 7) gives 7 = 4a − 5, so a = 3. The vertex is a constraint, not just another ordinary point.","math":null,"figure":null,"id":"lesson-10-q3","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Vertex constraint"},{"stem":"The model below satisfies f(0) = 7, f(1) = 11, and f(2) = 19. What is c?","choices":null,"answer":"3","why":"The successive differences are 4 and 8, so b=8/4=2. Then a(b−1)=4 gives a=4, and a+c=7 gives c=3. Verify: 4·2⁰+3=7, 4·2¹+3=11, and 4·2²+3=19.","math":"f(x)=ab^x+c,\\quad a>0,\\ b>1","figure":null,"id":"lesson-10-q4-v2","equations":["assets/lesson-10-q4-0.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Offset exponential growth","desmos":"Enter (0,7), (1,11), and (2,19) in a table. Fit y_1~a b^x_1+c with a>0 and b>1. Read c and substitute into all three original values."},{"stem":"Which dataset is sufficient to determine a unique quadratic f(x) = ax² + bx + c?","choices":["f(1) = 4 only","f(1) = 4 and f(2) = 9 only","f(1) = 4, f(2) = 9, and f(3) = 16","Three repeated copies of f(1) = 4"],"answer":"C","why":"Three distinct inputs impose three independent constraints on a quadratic. Repeated copies of a single observation do not add information.","math":null,"figure":null,"id":"lesson-10-q5","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Enough independent points"},{"stem":"A circle passes through (1, 2), (5, 2), and (3, 4). What is the y-coordinate of its center?","choices":null,"answer":"2","why":"The first two points force the center onto x = 3. Equal distances from (1, 2) and (3, 4) give 4 + (k − 2)² = (k − 4)², so k = 2.","math":null,"figure":null,"id":"lesson-10-q6","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Circle through three points"},{"stem":"The function below satisfies g(1) = 8 and g(4) = 2. What is g(2) + g(3)?","choices":null,"answer":"10","why":"Let z = x − 2.5. Inputs 1 and 4 have opposite z-values, so their odd-power terms cancel; g(1) + g(4) = 2c = 10. Inputs 2 and 3 also have opposite z-values, so their sum is the same.","math":"g(x)=a(x-2.5)^3+b(x-2.5)+c","figure":null,"id":"lesson-10-q7","equations":["assets/lesson-10-q7-0.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Symmetry and identifiable quantities"},{"stem":"A line is modeled by y = mx + b and passes through (−2, 9) and (4, −3). At what x-coordinate does it cross the x-axis?","choices":null,"answer":"2.5","why":"The slope is −12/6 = −2. Using (4, −3) gives b = 5. Set −2x + 5 = 0 to obtain x = 2.5.","math":null,"figure":null,"id":"lesson-10-q8","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Requested intercept"},{"stem":"A numerical fit returns a = 2 and b = 5 for y = ax² + b. Which check would expose an incorrect fit to the points (1, 7) and (3, 25)?","choices":["Verify the fit only at x = 0.","Check the original equations at both given inputs.","Accept the fit because both parameters are integers.","Remove the point with the larger input."],"answer":"B","why":"At x = 1 the model gives 7, but at x = 3 it gives 23 rather than 25. A plausible numerical output must still satisfy the original constraints.","math":null,"figure":null,"id":"lesson-10-q9","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Verify original observations"},{"stem":"A quadratic f(x) = ax² + c has f(−2) = 17 and f(3) = 42. What is c?","choices":null,"answer":"-3","why":"The equations are 4a + c = 17 and 9a + c = 42. Subtraction yields 5a = 25, so a = 5 and c = −3. The symmetric model has no linear term.","math":null,"figure":null,"id":"lesson-10-q10","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Restricted quadratic structure"},{"topic":"Standard-form fitting","stem":"A line has equation 4x + by = 24 and passes through (3, 2). What is b/4?","choices":null,"answer":"1.5","why":"Substitute the point: 12 + 2b = 24, so b = 6. The requested quantity is 6/4 = 1.5.","desmos":"Enter 4(3)+b(2)~24, then evaluate b/4. Keep the coefficient 4 fixed.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q11-v2"},{"topic":"Quadratic from three points","stem":"The table gives values of f(x) = ax² + bx + c. What is f(0)?","choices":null,"answer":"14","why":"The three distinct inputs determine f(x) = x² − 7x + 14. Substitution gives 8, 2, and 8; hence f(0) = 14.","desmos":"Enter the table, then y_1~a x_1^2+b x_1+c. Define f(x)=a x^2+b x+c and evaluate f(0).","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","y"],"rows":[[1,8],[3,2],[6,8]]},"id":"lesson-10-q12-v2"},{"topic":"Roots as model constraints","stem":"A quadratic has zeros −2 and 4 and satisfies f(1) = −27. What is f(0)?","choices":null,"answer":"-24","why":"Write f(x) = a(x + 2)(x − 4). Then −27 = −9a, so a = 3 and f(0) = 3(2)(−4) = −24.","desmos":"Use −27~a(1+2)(1−4), then evaluate a(0+2)(0−4). Alternatively, fit a factored model to the three known points.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q13-v2"},{"topic":"Vertex and maximum in context","stem":"A ball’s height h(t), in feet, is quadratic. Its maximum height is 45 feet at t = 2 seconds, and h(0) = 29. What is h(5)?","choices":null,"answer":"9","why":"Use h(t) = a(t − 2)² + 45. The initial height gives 29 = 4a + 45, so a = −4. Thus h(5) = −4(9) + 45 = 9.","desmos":"Enter 29~a(0−2)^2+45. Keep the vertex coordinates fixed, then evaluate a(5−2)^2+45.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q14-v2"},{"topic":"Transformed outputs","stem":"The table lists x and f(x) + 5, where f is quadratic. What is f(0)?","choices":null,"answer":"28","why":"The listed outputs fit 2(x − 4)² + 1. Since these are f(x) + 5, f(x) = 2(x − 4)² − 4; f(0) = 28.","desmos":"Fit y_1~a x_1^2+b x_1+c to the displayed outputs, then evaluate c−5. Do not mistake the listed y-values for f(x).","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","f(x) + 5"],"rows":[[2,9],[4,1],[6,9]]},"id":"lesson-10-q15-v2"},{"topic":"Unequal time intervals and growth","stem":"An exponential population model has P(2) = 180 and P(6) = 405. By what percent does the population increase every 2 years? Enter the percent as a number.","choices":null,"answer":"50","why":"Over 4 years the multiplier is 405/180 = 2.25. The positive 2-year multiplier is √2.25 = 1.5, which is a 50% increase.","desmos":"Fit y_1~a b^(x_1/2) using (2,180) and (6,405), with a>0 and b>0. Evaluate 100(b−1); the exponent makes b the 2-year factor.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q16-v2"},{"topic":"Exponential decay","stem":"A quantity follows Q(t) = abᵗ with a > 0 and 0 < b < 1. Q(1) = 250 and Q(4) = 128. What percent of the quantity is lost each year?","choices":null,"answer":"20","why":"The ratio is b³ = 128/250 = 0.512, so b = 0.8. Each year 20% is lost.","desmos":"Fit y_1~a b^x_1 to (1,250) and (4,128), using a>0 and 0<b<1. Evaluate 100(1−b).","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q17-v2"},{"topic":"Offset exponential decay","stem":"The table gives f(x) = abˣ + c, where a > 0 and 0 < b < 1. What is 2c?","choices":null,"answer":"18","why":"The successive changes are −6 and −3, so b = (−3)/(−6) = 0.5. Then a(b−1) = −6 gives a = 12; c = 21−12 = 9. Hence 2c = 18.","desmos":"Use y_1~a b^x_1+c with three points and the given parameter restrictions. Evaluate 2c and check all three outputs.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","y"],"rows":[[0,21],[1,15],[2,12]]},"id":"lesson-10-q18-v2"},{"topic":"Structured polynomial fitting","stem":"Let g(x) = a(x + 4)⁴ + b(x + 4)² + c. If g(−4) = 3, g(−3) = 8, and g(−2) = 35, what is g(−1)?","choices":null,"answer":"120","why":"The first value gives c = 3. The other two give a+b = 5 and 16a+4b = 32, so a = 1 and b = 4. At −1, g = 81+36+3 = 120.","desmos":"Fit y_1~a(x_1+4)^4+b(x_1+4)^2+c to the three inputs. Preserve the given structure; a general quartic would need more information.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q19-v2"},{"topic":"Circle fitting and radius","stem":"A circle passes through (−1, 3), (7, 3), and (3, 7). What is its radius squared?","choices":null,"answer":"16","why":"The first two points have midpoint (3,3); the third is 4 units above it. The circle centered at (3,3), with radius 4, passes through all three. Radius squared is 16.","desmos":"Enter the three points in a table and use (x_1−h)^2+(y_1−k)^2~s. The fitted s is r², not r.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q20-v2"},{"topic":"Noisy linear least-squares prediction","stem":"Use the least-squares line y = mx + b for all three points in the table. What value does this model predict at x = 4?","choices":null,"answer":"8.5","why":"The means are x̄ = 1 and ȳ = 4. The slope is Σ(x−1)(y−4)/Σ(x−1)² = 3/2. The intercept is 4−1.5 = 2.5. At 4, the prediction is 8.5; a best-fit line need not pass through every point.","desmos":"Enter y_1~m x_1+b, then evaluate 4m+b. This is noisy data: use all points rather than joining only two.","math":null,"equations":[],"difficulty":"Medium","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","y"],"rows":[[0,2],[1,5],[2,5]]},"id":"lesson-10-q21-v2"},{"topic":"Residual and units","stem":"A model predicts a plant’s height, in centimeters, using h(t) = 1.5t + 6, where t is days. At t = 8, the observed height is 15 centimeters. What is the residual, defined as observed minus predicted?","choices":null,"answer":"-3","why":"The predicted height is 1.5(8)+6 = 18 centimeters. The residual is 15−18 = −3 centimeters, indicating the observation is below the model.","desmos":"Define h(t)=1.5t+6, then evaluate 15−h(8). Keep observed-minus-predicted in that order.","math":null,"equations":[],"difficulty":"Medium","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q22-v2"},{"topic":"Selecting the model","stem":"The table lists exact outputs at equally spaced inputs. Which model family fits these values?","choices":["Linear: mx + b","Offset exponential: abˣ + c","Quadratic: ax² + bx + c","Constant: c"],"answer":"B","why":"The differences are 8, 16, and 32, so the changing part doubles. Subtracting the constant 3 gives 8, 16, 32, and 64, fitting 8·2ˣ+3. The original ratios are not constant.","desmos":"Fit candidate model families and compare residuals. An offset exponential needs a constant term; y_1~a b^x_1 alone will not fit exactly.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","y"],"rows":[[0,11],[1,19],[2,35],[3,67]]},"id":"lesson-10-q23-v2"},{"topic":"Scaling ambiguity","stem":"A line is written Ax + By = C, and only points on the line are supplied. All three coefficients are unknown. Which quantity can be uniquely determined for a nonvertical line?","choices":["A","B","−A/B","C"],"answer":"C","why":"Multiplying A, B, and C by the same nonzero number preserves the line. Individual coefficients are not unique. Solving for y gives y = −(A/B)x + C/B, so the slope −A/B is unique.","desmos":"Normalize the equation to y=m x+b before fitting. Do not interpret one arbitrary fitted A as uniquely required.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q24-v2"},{"topic":"Correct table headers and tilde","stem":"A Desmos table uses columns x₁ and y₁. You need to find the coefficients of an exact quadratic through its three distinct input values. Which entry fits those coefficients?","choices":["y = ax² + bx + c","y₁ ~ ax² + bx + c","y₁ ~ ax₁ + c","y₁ ~ ax₁² + bx₁ + c"],"answer":"D","why":"The tilde asks Desmos to fit parameters to the supplied lists. The model must use both table columns and include every unknown term.","desmos":"Type y_1~a x_1^2+b x_1+c. The underscore creates a subscript, and ~ is the regression symbol.","math":null,"equations":[],"difficulty":"Medium","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q25-v2"},{"topic":"Slope interpretation with scaled axes","stem":"A best-fit line is y = 2.4x + 18, where x is floor area in thousands of square feet and y is price in thousands of dollars. What increase in predicted price, in dollars, corresponds to an additional 500 square feet?","choices":null,"answer":"1200","why":"500 square feet is 0.5 x-units. The predicted change is 2.4(0.5)=1.2 thousand dollars, or $1,200.","desmos":"Evaluate 2.4(500/1000)×1000. Use the slope for a change; do not add the intercept.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q26-v2"},{"topic":"Average rate from observations","stem":"The table shows observed flight time, in hours, x days after April 1. What is the average rate of change from April 3 to April 9, in hours per day?","choices":null,"answer":"-1/3","why":"April 3 corresponds to x=2 and April 9 to x=8. The observed change is 7−9=−2 hours over 6 days, giving −1/3 hour per day. Intermediate values and a fitted line are unnecessary.","desmos":"Evaluate (7−9)/(8−2). Distinguish an observed average rate from a fitted slope.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["Days after April 1","Observed flight time (hours)"],"rows":[[2,9],[4,5],[6,11],[8,7]]},"id":"lesson-10-q27-v2"},{"topic":"Choose a line from a scatterplot","stem":"Which equation best models the trend of the five points in the scatterplot?","choices":["y = 0.5x + 3","y = 3x + 0.5","y = −0.5x + 7","y = 0.5x + 8"],"answer":"A","why":"The data rise by about 4 y-units over 8 x-units, with an intercept near 3. The least-squares line is exactly y=0.5x+3. The alternatives have an incorrect slope, direction, or intercept.","desmos":"Estimate the slope and intercept from the displayed scales first. If using a table, fit all five points rather than just the extreme observations.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"image":"assets/regression-scatter.svg","imageAlt":"Five observations at (0,3.5), (2,3), (4,5), (6,7), and (8,6.5), with an upward best-fit line crossing the y-axis at 3 and passing through (8,7).","id":"lesson-10-q28-v2"},{"topic":"Count overpredictions on a graph","stem":"The scatterplot shows five observations and the model y = 0.5x + 3. For how many observations does the model predict a value greater than the observed y-value?","choices":null,"answer":"2","why":"The points at x=2 and x=8 are below the line, so the model overpredicts those two. The points at x=0 and x=6 are above it, and the point at x=4 is on it.","desmos":"Compare each observed y-value with 0.5x+3. Count negative residuals; do not count a point on the line.","math":null,"equations":[],"difficulty":"Medium","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"image":"assets/regression-scatter.svg","imageAlt":"Five observations at (0,3.5), (2,3), (4,5), (6,7), and (8,6.5), with an upward best-fit line crossing the y-axis at 3 and passing through (8,7).","id":"lesson-10-q29-v2"},{"topic":"Rescaling a fitted data set","stem":"The least-squares line for data set E is y = 2x + 5. Data set F is created by multiplying every observed y-value by 3.9 while keeping x unchanged. What is the y-intercept of the least-squares line for F?","choices":null,"answer":"19.5","why":"Uniformly multiplying all outputs multiplies both fitted slope and intercept by the same factor. The new line is y=7.8x+19.5.","desmos":"Transform the fitted model to 3.9(2x+5), or multiply the table outputs by 3.9 and refit the same linear family.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q30-v2"},{"topic":"Equivalent exponential form showing a value","stem":"The function f(x) = 6·3ˣ is rewritten to display f(2) as its leading coefficient. Which equivalent form does this?","choices":["18·3<sup>x−2</sup>","54·3ˣ","54·3<sup>x−2</sup>","6·3<sup>x+2</sup>"],"answer":"C","why":"f(2)=6·9=54. The equivalent form is 54·3^(x−2), because 3^(x−2)=3ˣ/9.","desmos":"Evaluate f(2), then shift the exponent to x−2 and verify the coefficient adjustment.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q31-v2"},{"topic":"Input translation and quadratic minimum","stem":"The function f(x) = 2x² + 12x + 23 is used to define g(x) = f(x + 5). At what x-value does g reach its minimum?","choices":null,"answer":"-8","why":"Completing the square gives f(x)=2(x+3)²+5, minimized at input −3. For g, x+5 must equal −3, so x=−8.","desmos":"Define f(x)=2x^2+12x+23 and graph y=f(x+5). Read the vertex x-coordinate, checking the direction of the input shift.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-10-q32-v2"}],"coverage":["Linear model from two points","Exponential model from separated inputs","Vertex constraint","Offset exponential growth","Enough independent points","Circle through three points","Symmetry and identifiable quantities","Requested intercept","Verify original observations","Restricted quadratic structure","Standard-form fitting","Quadratic from three points","Roots as model constraints","Vertex and maximum in context","Transformed outputs","Unequal time intervals and growth","Exponential decay","Offset exponential decay","Structured polynomial fitting","Circle fitting and radius","Noisy linear least-squares prediction","Residual and units","Selecting the model","Scaling ambiguity","Correct table headers and tilde","Slope interpretation with scaled axes","Average rate from observations","Choose a line from a scatterplot","Count overpredictions on a graph","Rescaling a fitted data set","Equivalent exponential form showing a value","Input translation and quadratic minimum"],"coverageNote":"32 questions spanning the reviewed lesson methods and additional SAT/PSAT model-fitting situations, including your outlier weakness. A finite set cannot cover every possible wording or combination; use this checklist to find gaps."},{"id":"lesson-11","title":"Regression Part 2","day":5,"section":0,"url":"https://www.loom.com/share/90f282f4c7184bd2a5257492dc76b7b3","embed":"https://www.loom.com/embed/90f282f4c7184bd2a5257492dc76b7b3","questions":[{"stem":"The equation below has two positive solutions a. What is their product?","choices":null,"answer":"9","why":"Rearrange to a² − 10a + 9 = 0 = (a − 1)(a − 9). The solutions are 1 and 9, whose product is 9. One numerical regression result alone would miss the second solution.","math":"a+\\frac{9}{a}=10","figure":null,"id":"lesson-11-q1","equations":["assets/lesson-11-q1-0.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Multiple scalar roots","regressionSteps":{"setup":"First multiply the original equation by its nonzero variable to obtain z²−10z+9=0. Its two roots have sum 10 and product 9. Leave r and s undefined so Desmos fits both; do not fix either root with a slider.","entries":["[r+s,r*s]~[10,9]","r*s"],"check":"The fitted roots are 1 and 9 (possibly reversed), and r*s=9. Substitute both into z+9/z=10. A single scalar regression can find just one root; this setup fits the root pair."},"desmos":"First multiply the original equation by its nonzero variable to obtain z²−10z+9=0. Its two roots have sum 10 and product 9. Leave r and s undefined so Desmos fits both; do not fix either root with a slider. Type separately: [r+s,r*s]~[10,9]; r*s. The fitted roots are 1 and 9 (possibly reversed), and r*s=9. Substitute both into z+9/z=10. A single scalar regression can find just one root; this setup fits the root pair."},{"stem":"The identity below holds for all real x. What is p + q?","choices":null,"answer":"15","why":"Expand to x² + 8x + 16 − 9 = x² + 8x + 7. Thus p = 8 and q = 7, so p + q = 15.","math":"(x+4)^2-9=x^2+px+q","figure":null,"id":"lesson-11-q2","equations":["assets/lesson-11-q2-0.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Quadratic identity","regressionSteps":{"setup":"Here u is a list of three chosen inputs, while p and q are unknown scalar coefficients. Do not define p or q before fitting.","entries":["u=[0,1,2]","(u+4)^2-9~u^2+p*u+q","p+q"],"check":"p=8 and q=7, giving 15. Expanding both sides proves the identity beyond the sampled inputs; three distinct inputs suffice for the quadratic difference."},"desmos":"Here u is a list of three chosen inputs, while p and q are unknown scalar coefficients. Do not define p or q before fitting. Type separately: u=[0,1,2]; (u+4)^2-9~u^2+p*u+q; p+q. p=8 and q=7, giving 15. Expanding both sides proves the identity beyond the sampled inputs; three distinct inputs suffice for the quadratic difference."},{"stem":"The graphs below intersect at a point whose y-coordinate is 13. What is k?","choices":null,"answer":"5","why":"The known y-value gives 13 = 2x + 3, so x = 5. Then 13 = 5k − 12 gives k = 5. Fix the given y-value rather than fitting it as an additional unknown.","math":"y=2x+3,\\quad y=kx-12","figure":null,"id":"lesson-11-q3","equations":["assets/lesson-11-q3-0.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Known intersection output","regressionSteps":{"setup":"u is the unknown x-coordinate. The supplied y-coordinate stays 13 on both right sides. Leave u and k undefined. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["[2*u+3,k*u-12]~[13,13]"],"check":"u=5 and k=5. Both original lines give y=13 at x=5."},"desmos":"u is the unknown x-coordinate. The supplied y-coordinate stays 13 on both right sides. Leave u and k undefined. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: [2*u+3,k*u-12]~[13,13]. u=5 and k=5. Both original lines give y=13 at x=5."},{"stem":"A data set contains (0, 5), (1, 8), (2, 17), and (3, 34). The point (3, 34) is removed as an outlier. The remaining points lie exactly on f(x) = ax² + c. What is a/c?","choices":null,"answer":"0.6","why":"The input 0 gives c = 5. The input 1 gives a + 5 = 8, so a = 3. The input 2 verifies 4(3) + 5 = 17. Thus a/c = 3/5 = 0.6. Removing a point changes the fitted model; distinguish a coefficient from an output value.","math":null,"figure":null,"id":"lesson-11-q4","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Outlier removal and coefficient ratio","regressionSteps":{"setup":"The removed point (3,34) must not be entered. u and v are matching data lists, and a,c are undefined scalar parameters.","entries":["u=[0,1,2]","v=[5,8,17]","v~a*u^2+c","a/c"],"check":"a=3, c=5, and a/c=0.6. Every retained observation is matched exactly."},"desmos":"The removed point (3,34) must not be entered. u and v are matching data lists, and a,c are undefined scalar parameters. Type separately: u=[0,1,2]; v=[5,8,17]; v~a*u^2+c; a/c. a=3, c=5, and a/c=0.6. Every retained observation is matched exactly."},{"stem":"For all real x in the domain, the rational identity below holds. What is k?","choices":null,"answer":"2","why":"Factor the numerator as (x − 2)(x + 2). The simplified expression is x + 2 for x ≠ 2, so k = 2. Preserve the excluded input.","math":"\\frac{x^2-4}{x-2}=x+k\\quad(x\\ne2)","figure":null,"id":"lesson-11-q5","equations":["assets/lesson-11-q5-0.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Rational identity and domain","regressionSteps":{"setup":"Use inputs that avoid the excluded value 2. Multiply the identity by u−2 before regression to avoid fitting through a denominator. u is a list; k is the only unknown coefficient. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["u=[0,1,3]","u^2-4~(u+k)*(u-2)"],"check":"k=2. Factor x²−4=(x−2)(x+2) to confirm the identity for every allowed input, with x≠2 still excluded."},"desmos":"Use inputs that avoid the excluded value 2. Multiply the identity by u−2 before regression to avoid fitting through a denominator. u is a list; k is the only unknown coefficient. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: u=[0,1,3]; u^2-4~(u+k)*(u-2). k=2. Factor x²−4=(x−2)(x+2) to confirm the identity for every allowed input, with x≠2 still excluded."},{"stem":"The equations below have a common solution. What is 8ˣ/2ʸ?","choices":null,"answer":"16","why":"Write the ratio as 2^(3x − y). The first equation fixes the exponent at 4, so the ratio is 16 regardless of the individual coordinates.","math":"\\begin{gathered}3x-y=4\\\\x+y=8\\end{gathered}","figure":null,"id":"lesson-11-q6","equations":["assets/lesson-11-q6-0.png","assets/lesson-11-q6-1.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Invariant across a system","regressionSteps":{"setup":"a represents the unknown x and b represents the unknown y. Leave them undefined. Each list position pairs one original equation with its own constant.","entries":["[3*a-b,a+b]~[4,8]","8^a/2^b"],"check":"a=3, b=5, and 8³/2⁵=16. Check both equations, not just the first."},"desmos":"a represents the unknown x and b represents the unknown y. Leave them undefined. Each list position pairs one original equation with its own constant. Type separately: [3*a-b,a+b]~[4,8]; 8^a/2^b. a=3, b=5, and 8³/2⁵=16. Check both equations, not just the first."},{"stem":"For f(t) = t² + 2t, a positive number u satisfies f(u) = 35. What is u?","choices":null,"answer":"5","why":"u² + 2u − 35 = 0 factors as (u + 7)(u − 5). Positivity selects u = 5. Defining a function and fitting its input does not remove the need to check the input restriction.","math":null,"figure":null,"id":"lesson-11-q7","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Function input and positivity","regressionSteps":{"setup":"Define the given function with =. Use ~ to fit its unknown input u, with the positive-input restriction. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["f(t)=t^2+2*t","f(u)~35 {u>0}"],"check":"u=5. Check f(5)=35; the other algebraic root −7 is inadmissible."},"desmos":"Define the given function with =. Use ~ to fit its unknown input u, with the positive-input restriction. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: f(t)=t^2+2*t; f(u)~35 {u>0}. u=5. Check f(5)=35; the other algebraic root −7 is inadmissible."},{"stem":"A positive constant a satisfies a² + 2a = 15. What is a?","choices":null,"answer":"3","why":"The equation factors as (a+5)(a−3)=0. The positivity condition selects a=3. A numerical fit at −5 would satisfy the equation but violate the stated restriction.","math":null,"figure":null,"id":"lesson-11-q8-v3","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Positive-parameter scalar regression","regressionSteps":{"setup":"Leave a undefined and include the supplied positivity restriction. Do not type a=1 as a convenient slider value. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["a^2+2*a~15 {a>0}"],"check":"a=3. Substitution gives 9+6=15, while the negative root −5 is excluded."},"desmos":"Leave a undefined and include the supplied positivity restriction. Do not type a=1 as a convenient slider value. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: a^2+2*a~15 {a>0}. a=3. Substitution gives 9+6=15, while the negative root −5 is excluded."},{"stem":"The identity below holds for every real x. What is r?","choices":null,"answer":"6","why":"The x-coefficient on the left is −(2 + r). On the right it is −8, so r = 6. The constant s is 12.","math":"(x-2)(x-r)=x^2-8x+s","figure":null,"id":"lesson-11-q9","equations":["assets/lesson-11-q9-0.png"],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Factored polynomial identity","regressionSteps":{"setup":"u is the list of known test inputs; r and s are unknown parameters. Preserve the order of the expressions. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["u=[0,1,3]","(u-2)*(u-r)~u^2-8*u+s"],"check":"r=6 and s=12. Expansion verifies the fitted identity for all real x, not merely the selected inputs."},"desmos":"u is the list of known test inputs; r and s are unknown parameters. Preserve the order of the expressions. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: u=[0,1,3]; (u-2)*(u-r)~u^2-8*u+s. r=6 and s=12. Expansion verifies the fitted identity for all real x, not merely the selected inputs."},{"stem":"The table gives values of the quadratic f(x)=ax²+bx+c. What is the constant term c?","choices":null,"answer":"60","why":"The unique quadratic is f(x)=3x²−36x+60. Substituting the three listed inputs gives 27, −21, and −45. Thus c=60.","math":null,"figure":{"type":"table","headers":["x","f(x)"],"rows":[[1,27],[3,-21],[5,-45]]},"id":"lesson-11-q10-v3","equations":[],"difficulty":"Hard","hardFocus":"Model selection, parameter constraints, outliers, and exact verification","topic":"Quadratic coefficient recovery","regressionSteps":{"setup":"Use all three supplied observations and the full quadratic model. Leave a,b,c undefined. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["u=[1,3,5]","v=[27,-21,-45]","v~a*u^2+b*u+c"],"check":"a=3, b=−36, c=60. Substitute each given x to check the original table."},"desmos":"Use all three supplied observations and the full quadratic model. Leave a,b,c undefined. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: u=[1,3,5]; v=[27,-21,-45]; v~a*u^2+b*u+c. a=3, b=−36, c=60. Substitute each given x to check the original table."},{"topic":"Simultaneous nonlinear constraints","stem":"Positive constants a and b satisfy a + b = 7 and ab = 10. What is a² + b²?","choices":null,"answer":"29","why":"(a+b)² = a²+b²+2ab, so a²+b² = 49−20 = 29. The ordered solutions are (2,5) and (5,2), and both give 29.","desmos":"Both a and b are unknown. Do not fix a at 1: that would add an unsupported constraint. Type separately: [a+b,a*b]~[7,10] {a>0} {b>0}; a^2+b^2. The two parameters are 2 and 5, possibly reversed. Their squared sum is 29, and both original constraints hold.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q11-v2","regressionSteps":{"setup":"Both a and b are unknown. Do not fix a at 1: that would add an unsupported constraint.","entries":["[a+b,a*b]~[7,10] {a>0} {b>0}","a^2+b^2"],"check":"The two parameters are 2 and 5, possibly reversed. Their squared sum is 29, and both original constraints hold."}},{"topic":"List order and all constraints","stem":"Constants satisfy 2a + b = 11, a − b = 1, and 3a + 2b = 18. Which regression setup preserves all three equations?","choices":["[2a+b, a−b, 3a+2b] ~ [11, 1, 18]","[2a+b, a−b, 3a+2b] ~ [1, 11, 18]","[2a+b, a−b] ~ [11, 18]","[2a+b, a+b, 3a+2b] ~ [11, 1, 18]"],"answer":"A","why":"Each left expression must be paired with its own right-hand value in the same list position. The solution a=4, b=3 satisfies all three equations.","desmos":"This is choice A. Leave a,b undefined, and keep the two lists in matching equation order. Type separately: [2*a+b,a-b,3*a+2*b]~[11,1,18]. a=4 and b=3 satisfy every list entry. A swapped right-hand list solves a different problem.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q12-v2","regressionSteps":{"setup":"This is choice A. Leave a,b undefined, and keep the two lists in matching equation order.","entries":["[2*a+b,a-b,3*a+2*b]~[11,1,18]"],"check":"a=4 and b=3 satisfy every list entry. A swapped right-hand list solves a different problem."}},{"topic":"Polynomial identity beyond quadratics","stem":"For every real x, (x + 2)³ − 3x = x³ + px² + qx + r. What is p + q + r?","choices":null,"answer":"23","why":"Expansion gives x³+6x²+9x+8, so p=6, q=9, and r=8. Their sum is 23.","desmos":"u is a known list; p,q,r are undefined coefficients. The known cubic term is kept fixed rather than fitted. Type separately: u=[0,1,2]; (u+2)^3-3*u~u^3+p*u^2+q*u+r; p+q+r. p=6, q=9, r=8, and the sum is 23. The cubic terms cancel, leaving a quadratic difference; verify by expansion.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q13-v2","regressionSteps":{"setup":"u is a known list; p,q,r are undefined coefficients. The known cubic term is kept fixed rather than fitted.","entries":["u=[0,1,2]","(u+2)^3-3*u~u^3+p*u^2+q*u+r","p+q+r"],"check":"p=6, q=9, r=8, and the sum is 23. The cubic terms cancel, leaving a quadratic difference; verify by expansion."}},{"topic":"Rational identity by regression","stem":"For every x ≠ 3, (2x² + px + q)/(x − 3) = 2x + 5. What is p + q?","choices":null,"answer":"-16","why":"Multiplication by x−3 gives 2x²+px+q=2x²−x−15. Therefore p=−1 and q=−15, so p+q=−16. The original domain still excludes x=3.","desmos":"Multiply the original identity by x−3 before fitting. These sample inputs avoid the excluded value 3. Leave p,q undefined. Type separately: u=[0,1,2]; 2*u^2+p*u+q~(2*u+5)*(u-3); p+q. p=−1, q=−15, giving −16. Multiply the identity by x−3 to verify it over its original domain.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q14-v3","regressionSteps":{"setup":"Multiply the original identity by x−3 before fitting. These sample inputs avoid the excluded value 3. Leave p,q undefined.","entries":["u=[0,1,2]","2*u^2+p*u+q~(2*u+5)*(u-3)","p+q"],"check":"p=−1, q=−15, giving −16. Multiply the identity by x−3 to verify it over its original domain."}},{"topic":"Integer factor structure","stem":"For all real x, (x + p)(x + q) = x² + 13x + 40, where p and q are positive integers and p < q. What is q − p?","choices":null,"answer":"3","why":"The constants satisfy p+q=13 and pq=40, so they are 5 and 8. The ordering gives p=5, q=8 and q−p=3.","desmos":"Expand the two factors to read the sum and product constraints. The sum 13 and ordering p<q imply p<6.5<q; these bounds select the correct ordering. Type separately: [p+q,p*q]~[13,40] {0<p<6.5} {q>6.5}; q-p. p=5, q=8, and q−p=3. Verify both numbers are positive integers and the expanded polynomial agrees.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q15-v2","regressionSteps":{"setup":"Expand the two factors to read the sum and product constraints. The sum 13 and ordering p<q imply p<6.5<q; these bounds select the correct ordering.","entries":["[p+q,p*q]~[13,40] {0<p<6.5} {q>6.5}","q-p"],"check":"p=5, q=8, and q−p=3. Verify both numbers are positive integers and the expanded polynomial agrees."}},{"topic":"Exponential identities and common bases","stem":"For every real x, 9<sup>2x + 1</sup> = 3<sup>px + q</sup>. What is p + q?","choices":null,"answer":"6","why":"Since 9=3², the left side is 3^(4x+2). Equal exponents for all x give p=4 and q=2, totaling 6.","desmos":"u contains two distinct known inputs. Leave p,q undefined; fit the original exponential expressions. Type separately: u=[0,1]; 9^(2*u+1)~3^(p*u+q); p+q. p=4 and q=2, giving 6. Check the all-input identity by rewriting 9 as 3².","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q16-v2","regressionSteps":{"setup":"u contains two distinct known inputs. Leave p,q undefined; fit the original exponential expressions.","entries":["u=[0,1]","9^(2*u+1)~3^(p*u+q)","p+q"],"check":"p=4 and q=2, giving 6. Check the all-input identity by rewriting 9 as 3²."}},{"topic":"Known intersection coordinate","stem":"The graphs y = x² + 1 and y = kx + 3 intersect at a point with y-coordinate 10 and positive x-coordinate. What is k?","choices":null,"answer":"7/3","why":"The known output gives x²+1=10, so x=3 under the positivity restriction. Then 10=3k+3, giving k=7/3.","desmos":"u is the unknown x-coordinate and k is an unknown slope. Keep the known output 10 fixed in both entries. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: [u^2+1,k*u+3]~[10,10] {u>0}. u=3 and k=7/3. Both graphs produce y=10. The positivity restriction excludes u=−3.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q17-v2","regressionSteps":{"setup":"u is the unknown x-coordinate and k is an unknown slope. Keep the known output 10 fixed in both entries. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["[u^2+1,k*u+3]~[10,10] {u>0}"],"check":"u=3 and k=7/3. Both graphs produce y=10. The positivity restriction excludes u=−3."}},{"topic":"Regressing a composed input","stem":"Let f(x) = x² − 3x and g(x) = ax + 1. If f(g(2)) = 10 and g(2) > 0, what is g(3)?","choices":null,"answer":"7","why":"Let u=g(2). Then u²−3u−10=(u−5)(u+2)=0. Positivity gives u=5, so 2a+1=5 and a=2. Therefore g(3)=7.","desmos":"Define the supplied outer function first. Since g(2)=2a+1>0, the equivalent regression bound is a>−0.5. Type separately: f(t)=t^2-3*t; f(2*a+1)~10 {a>-0.5}; 3*a+1. a=2 and g(3)=7. Check f(g(2))=f(5)=10 and g(2)>0.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q18-v2","regressionSteps":{"setup":"Define the supplied outer function first. Since g(2)=2a+1>0, the equivalent regression bound is a>−0.5.","entries":["f(t)=t^2-3*t","f(2*a+1)~10 {a>-0.5}","3*a+1"],"check":"a=2 and g(3)=7. Check f(g(2))=f(5)=10 and g(2)>0."}},{"topic":"Radical equation and extraneous solution","stem":"A real number a satisfies √(a + 4) = a − 2. What is a?","choices":null,"answer":"5","why":"The right side must be nonnegative, so a≥2. Squaring gives a+4=a²−4a+4, hence a(a−5)=0. Only a=5 satisfies the original equation; a=0 is extraneous.","desmos":"Square both sides to obtain a+4=(a−2)², but keep a≥2 because the original square root equals the nonnegative quantity a−2. The restriction removes the extraneous squared root. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: a+4~(a-2)^2 {a>=2}. a=5, and sqrt(9)=3=5−2. Check the original unsquared equation.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q19-v2","regressionSteps":{"setup":"Square both sides to obtain a+4=(a−2)², but keep a≥2 because the original square root equals the nonnegative quantity a−2. The restriction removes the extraneous squared root. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["a+4~(a-2)^2 {a>=2}"],"check":"a=5, and sqrt(9)=3=5−2. Check the original unsquared equation."}},{"topic":"Tangency and minimum parameter","stem":"The equation √(k − x) = 40 − x has exactly one real solution. What is the minimum possible value of 4k?","choices":null,"answer":"159","why":"Set t=40−x≥0. Squaring gives k=40+t²−t=(t−1/2)²+159/4. The smallest k is 159/4 at t=1/2, and this valid t yields one solution. Thus the minimum 4k is 159.","desmos":"Squaring the original equation gives x²−79x+1600−k=0. For the minimum parameter with one solution, the quadratic touches zero at its vertex x=v. The second equation 2v−79=0 places v at that vertex; the first places it on the quadratic. Leave v,k undefined. Type separately: [v^2-79*v+1600-k,2*v-79]~[0,0]; 4*k. v=39.5 and k=39.75, so 4k=159. Check sqrt(k−v)=0.5=40−v. Smaller k puts the quadratic minimum above zero; squaring alone does not establish admissibility.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q20-v2","regressionSteps":{"setup":"Squaring the original equation gives x²−79x+1600−k=0. For the minimum parameter with one solution, the quadratic touches zero at its vertex x=v. The second equation 2v−79=0 places v at that vertex; the first places it on the quadratic. Leave v,k undefined.","entries":["[v^2-79*v+1600-k,2*v-79]~[0,0]","4*k"],"check":"v=39.5 and k=39.75, so 4k=159. Check sqrt(k−v)=0.5=40−v. Smaller k puts the quadratic minimum above zero; squaring alone does not establish admissibility."}},{"topic":"Structured polynomial with enough constraints","stem":"Let f(x)=a(x−2)³+b(x−2)+c. If f(0)=−5, f(3)=9, and f(4)=17, what is c?","choices":null,"answer":"6","why":"The three distinct constraints determine a=5/6, b=13/6, and c=6. The symmetric outputs f(0)+f(4)=12 also confirm 2c=12. Unlike the earlier two-point version, this fit determines all three coefficients.","desmos":"Use the exact given polynomial structure with three independent observations. Do not replace it with a general cubic containing four unknown coefficients. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: u=[0,3,4]; v=[-5,9,17]; v~a*(u-2)^3+b*(u-2)+c. a=5/6, b=13/6, c=6. All original values match; f(0)+f(4)=2c is a useful independent check.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q21-v3","regressionSteps":{"setup":"Use the exact given polynomial structure with three independent observations. Do not replace it with a general cubic containing four unknown coefficients. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["u=[0,3,4]","v=[-5,9,17]","v~a*(u-2)^3+b*(u-2)+c"],"check":"a=5/6, b=13/6, c=6. All original values match; f(0)+f(4)=2c is a useful independent check."}},{"topic":"Overconstraint and nonzero residuals","stem":"A regression is used for a+b=5, a−b=1, and 2a=10. It returns numbers with nonzero residuals. Which conclusion is correct?","choices":["The returned values necessarily solve all three equations.","Use only the last equation and ignore the others.","There is no exact common solution to all three equations.","Any tiny change to the constants guarantees an exact solution."],"answer":"C","why":"The first two equations force a=3 and b=2, contradicting 2a=10. No pair solves all three. A least-squares compromise is not an exact common solution.","desmos":"Enter all three supplied equations, with a,b undefined. This question deliberately asks you to recognize an inconsistent regression rather than report a nonexistent exact solution. Type separately: [a+b,a-b,2*a]~[5,1,10]. The least-squares compromise is a=13/3, b=2, with nonzero RMSE about 1.3333. The first two equations demand a=3,b=2 but then 2a=6, not 10. Therefore choice C is correct. A numerical fit does not certify an exact solution.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q22-v2","regressionSteps":{"setup":"Enter all three supplied equations, with a,b undefined. This question deliberately asks you to recognize an inconsistent regression rather than report a nonexistent exact solution.","entries":["[a+b,a-b,2*a]~[5,1,10]"],"check":"The least-squares compromise is a=13/3, b=2, with nonzero RMSE about 1.3333. The first two equations demand a=3,b=2 but then 2a=6, not 10. Therefore choice C is correct. A numerical fit does not certify an exact solution."}},{"topic":"Quadratic outlier at the center: coefficient changes","stem":"The table is fitted by least squares to y = ax² + c using all five points. The unusually high point (0,12) is then removed, and the same model is refitted to the remaining four points. Which changes occur?","choices":["a increases; c decreases.","a decreases; c increases.","Both a and c increase.","a is unchanged; c decreases."],"answer":"A","why":"Using all five points gives a=1 and c=8.4. After removing (0,12), every remaining point lies on y=2x²+5, so a=2 and c=5. Therefore a increases and c decreases. Both coefficients change; c is not simply the original observed value at x=0 in a noisy fit.","desmos":"Record a and c from the first fit. Then edit only the two data-list lines to u=[-2,-1,1,2] and v=[13,7,7,13], leaving the model unchanged. The removed x and y must occupy matching positions. Type separately: u=[-2,-1,0,1,2]; v=[13,7,12,7,13]; v~a*u^2+c. Before: a=1, c=8.4. After: a=2, c=5. Thus a increases and c decreases, choice A. The first noisy fit has nonzero error; the retained four points fit exactly.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","y"],"rows":[[-2,13],[-1,7],[0,12],[1,7],[2,13]]},"id":"lesson-11-q23-v2","regressionSteps":{"setup":"Record a and c from the first fit. Then edit only the two data-list lines to u=[-2,-1,1,2] and v=[13,7,7,13], leaving the model unchanged. The removed x and y must occupy matching positions.","entries":["u=[-2,-1,0,1,2]","v=[13,7,12,7,13]","v~a*u^2+c"],"check":"Before: a=1, c=8.4. After: a=2, c=5. Thus a increases and c decreases, choice A. The first noisy fit has nonzero error; the retained four points fit exactly."}},{"topic":"Off-center outlier: opposite coefficient changes","stem":"Fit the table by least squares to y = ax² + c, with no linear term. Remove the high point (2,23) and refit the same model. How do the coefficients change?","choices":["a increases; c decreases.","a decreases; c increases.","Both coefficients decrease.","Both coefficients stay unchanged."],"answer":"B","why":"For all five points, fitting gives a=24/7 and c=29/7. The four retained points lie exactly on y=2x²+5. Thus a decreases while c increases. Removing a high outlier does not always lower c; its location and model matter.","desmos":"Record both coefficients. Remove the final observation by editing u=[-2,-1,0,1] and v=[13,7,5,7]. Keep the specified model without a linear term. Type separately: u=[-2,-1,0,1,2]; v=[13,7,5,7,23]; v~a*u^2+c. Before: a=24/7, c=29/7. After: a=2, c=5. Thus a decreases and c increases, choice B. Do not assume all high outliers change c in the same direction.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","y"],"rows":[[-2,13],[-1,7],[0,5],[1,7],[2,23]]},"id":"lesson-11-q24-v2","regressionSteps":{"setup":"Record both coefficients. Remove the final observation by editing u=[-2,-1,0,1] and v=[13,7,5,7]. Keep the specified model without a linear term.","entries":["u=[-2,-1,0,1,2]","v=[13,7,5,7,23]","v~a*u^2+c"],"check":"Before: a=24/7, c=29/7. After: a=2, c=5. Thus a decreases and c increases, choice B. Do not assume all high outliers change c in the same direction."}},{"topic":"Factor condition as a parameter constraint","stem":"If k − x is a factor of −x² + (n/17)k², where k > 0, what is n?","choices":null,"answer":"17","why":"A factor k−x forces a zero at x=k. Substitution gives −k²+(n/17)k²=0. Since k≠0, divide by k² to get −1+n/17=0; hence n=17.","desmos":"First use the factor theorem: substitute x=k. Divide −k²+(n/17)k²=0 by the nonzero k² to eliminate the unspecified constant k. Leave n undefined. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: -1+n/17~0. n=17. The regression solves the reduced parameter condition. It cannot invent the factor-theorem step for you.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q25-v2","regressionSteps":{"setup":"First use the factor theorem: substitute x=k. Divide −k²+(n/17)k²=0 by the nonzero k² to eliminate the unspecified constant k. Leave n undefined. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["-1+n/17~0"],"check":"n=17. The regression solves the reduced parameter condition. It cannot invent the factor-theorem step for you."}},{"topic":"Compare fitted growth models","stem":"Account A is modeled by A(t)=1000bᵗ, with b>1, and has balances A(1)=1040 and A(2)=1081.60. Account B is modeled by B(t)=1000+mt and has balances B(1)=1040 and B(2)=1080. What is 1000(b−1)+m?","choices":null,"answer":"80","why":"The exponential data give b=1.04, and the linear data give m=40. Therefore 1000(0.04)+40=80. Both second-year observations verify their respective fitted models.","desmos":"Fit the exponential base b and the linear slope m in separate regressions, keeping the supplied initial balance 1000 fixed. Type separately: [1000*b,1000*b*b]~[1040,1081.6] {b>1}; [1000+m,1000+2*m]~[1040,1080]; 1000*(b-1)+m. b=1.04, m=40, and the requested value is 80. Both models reproduce their respective first- and second-year balances.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q26-v3","regressionSteps":{"setup":"Fit the exponential base b and the linear slope m in separate regressions, keeping the supplied initial balance 1000 fixed.","entries":["[1000*b,1000*b*b]~[1040,1081.6] {b>1}","[1000+m,1000+2*m]~[1040,1080]","1000*(b-1)+m"],"check":"b=1.04, m=40, and the requested value is 80. Both models reproduce their respective first- and second-year balances."}},{"topic":"Recover a growth-period parameter","stem":"A population is modeled by P(t)=500(1.06)<sup>t/n</sup>, where t is months and n>0. If P(6)=561.8, what is n?","choices":null,"answer":"3","why":"Since 561.8/500=1.1236=1.06², the exponent 6/n equals 2. Hence n=3 months. Substitution gives 500(1.06)²=561.8.","desmos":"Let p=6/n be the unknown positive number of growth periods in six months. Regress p, then calculate n=6/p. This change of variable preserves the original model. Type separately: 500*1.06^p~561.8 {p>0}; 6/p. p=2, so n=6/2=3 months. Check 500(1.06)²=561.8 in the original model.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q27-v3","regressionSteps":{"setup":"Let p=6/n be the unknown positive number of growth periods in six months. Regress p, then calculate n=6/p. This change of variable preserves the original model.","entries":["500*1.06^p~561.8 {p>0}","6/p"],"check":"p=2, so n=6/2=3 months. Check 500(1.06)²=561.8 in the original model."}},{"topic":"Inverse exponential input","stem":"A quantity follows Q(t)=120·2<sup>t/3</sup>, where t is years. At what t does the quantity reach 960?","choices":null,"answer":"9","why":"960/120=8=2³. Thus t/3=3 and t=9 years.","desmos":"Let p=t/3 be the unknown exponent. Regress p, then multiply by 3 to recover the requested time t. Do not fix p or t with a slider. Type separately: 120*2^p~960; 3*p. p=3, so t=9 years. Check 120·2³=960. The regression exponent itself is not the requested time.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q28-v2","regressionSteps":{"setup":"Let p=t/3 be the unknown exponent. Regress p, then multiply by 3 to recover the requested time t. Do not fix p or t with a slider.","entries":["120*2^p~960","3*p"],"check":"p=3, so t=9 years. Check 120·2³=960. The regression exponent itself is not the requested time."}},{"topic":"Offset exponential with separated inputs","stem":"The function f(x)=abˣ+c, with a>0 and b>1, satisfies f(0)=10, f(2)=16, and f(4)=40. What is c?","choices":null,"answer":"8","why":"Across each two-input interval the output changes are 6 and 24. Their ratio is b²=4, so b=2. Then 3a=6 gives a=2, and a+c=10 gives c=8. All three observations are reproduced.","desmos":"The input gaps are two units, and the exact model includes an offset c. Leave a,b,c undefined, and fit the actual supplied x-values. Read the requested letter directly under Regression Parameters; do not create a separate slider for it. Type separately: u=[0,2,4]; v=[10,16,40]; v~a*b^u+c {a>0} {b>1}. a=2, b=2, c=8. All three outputs match. Ignoring the input gaps or omitting the offset changes the problem.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q29-v3","regressionSteps":{"setup":"The input gaps are two units, and the exact model includes an offset c. Leave a,b,c undefined, and fit the actual supplied x-values. Read the requested letter directly under Regression Parameters; do not create a separate slider for it.","entries":["u=[0,2,4]","v=[10,16,40]","v~a*b^u+c {a>0} {b>1}"],"check":"a=2, b=2, c=8. All three outputs match. Ignoring the input gaps or omitting the offset changes the problem."}},{"topic":"Reciprocal model fitting","stem":"The function f(x)=a/x+b, for x>0, satisfies f(2)=11 and f(5)=5. What is f(4)?","choices":null,"answer":"6","why":"Subtracting gives a(1/2−1/5)=6, so a=20. Then 20/5+b=5 gives b=1. Thus f(4)=20/4+1=6.","desmos":"Multiply y=a/x+b by its nonzero input x to get xy=a+bx. Fit this equivalent relation using the supplied positive inputs, then evaluate f(4)=(a+4b)/4. Type separately: u=[2,5]; v=[11,5]; u*v~a+b*u; (a+4*b)/4. a=20, b=1, and f(4)=6. Check both observations in the original formula.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q30-v2","regressionSteps":{"setup":"Multiply y=a/x+b by its nonzero input x to get xy=a+bx. Fit this equivalent relation using the supplied positive inputs, then evaluate f(4)=(a+4b)/4.","entries":["u=[2,5]","v=[11,5]","u*v~a+b*u","(a+4*b)/4"],"check":"a=20, b=1, and f(4)=6. Check both observations in the original formula."}},{"topic":"Radical model: square outputs carefully","stem":"The model y=√(ax+b) passes through (0,4) and (3,5). What is a+b?","choices":null,"answer":"19","why":"Squaring the given nonnegative outputs gives b=16 and 3a+b=25, so a=3. Both original points satisfy the positive square root model; a+b=19.","desmos":"Square the known nonnegative outputs to get a linear fit in a,b. Here v is a data list, and v² means squaring each observation, not creating a nested list. Type separately: u=[0,3]; v=[4,5]; v^2~a*u+b; a+b. a=3, b=16, and a+b=19. Verify sqrt(16)=4 and sqrt(25)=5 in the original radical model.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":null,"id":"lesson-11-q31-v2","regressionSteps":{"setup":"Square the known nonnegative outputs to get a linear fit in a,b. Here v is a data list, and v² means squaring each observation, not creating a nested list.","entries":["u=[0,3]","v=[4,5]","v^2~a*u+b","a+b"],"check":"a=3, b=16, and a+b=19. Verify sqrt(16)=4 and sqrt(25)=5 in the original radical model."}},{"topic":"Fitted quadratic to root information","stem":"The table gives exact values of f(x)=ax²+bx+c. What is the sum of the two real zeros of f?","choices":null,"answer":"5","why":"The data determine f(x)=2x²−10x+8=2(x−1)(x−4). Its roots are 1 and 4, totaling 5. Equivalently, use −b/a, not b/a or c/a.","desmos":"Fit the full quadratic using all three exact points. For a quadratic, the sum of its two roots is −b/a; this final algebraic fact connects the fit to the requested quantity. Type separately: u=[0,2,3]; v=[8,-4,-4]; v~a*u^2+b*u+c; -b/a. a=2, b=−10, c=8. The sum is 5; independently factor 2(x−1)(x−4) to verify the real roots.","math":null,"equations":[],"difficulty":"Hard","hardFocus":"Choose the correct model, preserve constraints, and verify the requested quantity","figure":{"type":"table","headers":["x","y"],"rows":[[0,8],[2,-4],[3,-4]]},"id":"lesson-11-q32-v2","regressionSteps":{"setup":"Fit the full quadratic using all three exact points. For a quadratic, the sum of its two roots is −b/a; this final algebraic fact connects the fit to the requested quantity.","entries":["u=[0,2,3]","v=[8,-4,-4]","v~a*u^2+b*u+c","-b/a"],"check":"a=2, b=−10, c=8. The sum is 5; independently factor 2(x−1)(x−4) to verify the real roots."}}],"coverage":["Multiple scalar roots","Quadratic identity","Known intersection output","Outlier removal and coefficient ratio","Rational identity and domain","Invariant across a system","Function input and positivity","Positive-parameter scalar regression","Factored polynomial identity","Quadratic coefficient recovery","Simultaneous nonlinear constraints","List order and all constraints","Polynomial identity beyond quadratics","Rational identity by regression","Integer factor structure","Exponential identities and common bases","Known intersection coordinate","Regressing a composed input","Radical equation and extraneous solution","Tangency and minimum parameter","Structured polynomial with enough constraints","Overconstraint and nonzero residuals","Quadratic outlier at the center: coefficient changes","Off-center outlier: opposite coefficient changes","Factor condition as a parameter constraint","Compare fitted growth models","Recover a growth-period parameter","Inverse exponential input","Offset exponential with separated inputs","Reciprocal model fitting","Radical model: square outputs carefully","Fitted quadratic to root information"],"coverageNote":"32 questions spanning the reviewed lesson methods and additional SAT/PSAT model-fitting situations, including your outlier weakness. A finite set cannot cover every possible wording or combination; use this checklist to find gaps.","regressionGuide":"Start each question in a fresh graph. Leave fitted scalar letters undefined; defining a=1 fixes a instead of fitting it. Use u and v for supplied data lists, and matching lists for simultaneous equations. Type ~ for regression and = for definitions. Exact fits should have error essentially zero; the outlier and inconsistent-system exercises explain why their initial fits do not. Always check the original equations and restrictions. When typing a fraction, radical, or exponent, use the Right Arrow to move out of it before continuing on the main line. Check that the tilde is between the two complete sides, not inside a fraction or root. Type the displayed lines rather than treating them as generic pasted text. Wait until the fitted parameters appear before entering the next line. Do not click Add slider for a letter you intend to fit."},{"id":"lesson-12","title":"Isolation","day":6,"section":0,"url":"https://www.loom.com/share/e27524474ea24f1caeab97e2f5a99af4","embed":"https://www.loom.com/embed/e27524474ea24f1caeab97e2f5a99af4","questions":[{"stem":"Which equation expresses I in terms of Q, A, and L, where L ≠ 0?","choices":["I = A − QL","I = QL − A","I = (A − Q)/L","I = A/Q − L"],"answer":"A","why":"Multiply by L to obtain QL = A − I. Then I = A − QL.","math":"Q=\\frac{A-I}{L}","figure":null,"id":"lesson-12-q1","equations":["assets/lesson-12-q1-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"A sphere has volume V and positive radius r. Which expression gives r?","choices":["√(3V/(4π))","∛(3V/(4π))","4πV/3","3V/(4π)"],"answer":"B","why":"From V = (4/3)πr³, obtain r³ = 3V/(4π) and take the positive cube root.","math":"V=\\frac43\\pi r^3","figure":null,"id":"lesson-12-q2","equations":["assets/lesson-12-q2-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Which expression gives t in the equation below when v + u ≠ 0?","choices":["2s/(v − u)","2s/(v + u)","s(v + u)/2","s/(2v + 2u)"],"answer":"B","why":"Multiply by 2 and divide by u + v: t = 2s/(u + v). The denominator must be nonzero.","math":"s=\\frac{u+v}{2}t","figure":null,"id":"lesson-12-q3","equations":["assets/lesson-12-q3-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Which equation expresses x in terms of y, where y ≠ 3?","choices":["x = (2y + 5)/(y − 3)","x = (2y − 5)/(y + 3)","x = (3y − 5)/(y − 2)","x = (y − 3)/(2y + 5)"],"answer":"A","why":"Multiply y(x − 2) = 3x + 5. Collect x-terms: x(y − 3) = 2y + 5, then divide by y − 3.","math":"y=\\frac{3x+5}{x-2}","figure":null,"id":"lesson-12-q4","equations":["assets/lesson-12-q4-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Which equation expresses h in terms of A, a, and b when a + b ≠ 0?","choices":["h = 2A/(a + b)","h = A/(2a + 2b)","h = 2A(a + b)","h = (a + b)/(2A)"],"answer":"A","why":"The trapezoid area formula is A = (a + b)h/2. Multiplying by 2 and dividing by a + b isolates h.","math":"A=\\frac{a+b}{2}h","figure":null,"id":"lesson-12-q5","equations":["assets/lesson-12-q5-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Positive numbers x and y satisfy y = 5x². When y = 180, what is x?","choices":null,"answer":"6","why":"x² = 36, and positivity selects x = 6. Without positivity, both 6 and −6 would solve the equation.","math":null,"figure":null,"id":"lesson-12-q6","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Which formula expresses b in terms of c and a, where c ≠ 1?","choices":["b = a/(c − 1)","b = a/(c + 1)","b = a(c − 1)","b = (c − 1)/a"],"answer":"A","why":"Multiply by b: cb = a + b. Then b(c − 1) = a, so b = a/(c − 1), with the original requirement b ≠ 0 still applying.","math":"c=\\frac{a+b}{b}","figure":null,"id":"lesson-12-q7","equations":["assets/lesson-12-q7-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"}]},{"id":"lesson-13","title":"Factoring","day":6,"section":0,"url":"https://www.loom.com/share/0f4882ef88fc4b9198f7bc29e5100668","embed":"https://www.loom.com/embed/0f4882ef88fc4b9198f7bc29e5100668","questions":[{"stem":"The polynomial x² + kx − 24 has x − 3 as a factor. What is k?","choices":null,"answer":"5","why":"The factor theorem gives 3² + 3k − 24 = 0, so 3k = 15 and k = 5.","math":null,"figure":null,"id":"lesson-13-q1","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"The polynomial below has x + 2 as a factor. What is a?","choices":null,"answer":"-5","why":"Substitute x = −2: 2(4) − 2a − 18 = 0. Therefore −2a = 10 and a = −5.","math":"2x^2+ax-18","figure":null,"id":"lesson-13-q2","equations":["assets/lesson-13-q2-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Which polynomial has x − 4 as a factor?","choices":["x² − 4x + 4","x² − 7x + 12","x² + 7x + 12","x² − 2x − 12"],"answer":"B","why":"At x = 4, the second polynomial is 16 − 28 + 12 = 0; it factors as (x − 3)(x − 4). The other values are 4, 56, and −4.","math":null,"figure":null,"id":"lesson-13-q3","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"The polynomial (x − 5)(x + 1) is written as x² + bx + c. What is b − c?","choices":null,"answer":"1","why":"Expand to x² − 4x − 5. Thus b = −4 and c = −5, so b − c = 1.","math":null,"figure":null,"id":"lesson-13-q4","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"For a positive constant r, x − r is a factor of x² − 49. What is r?","choices":null,"answer":"7","why":"The roots are −7 and 7. Since r > 0, the factor x − r must be x − 7.","math":null,"figure":null,"id":"lesson-13-q5","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"The polynomials below share the factor x − 2. What is m + n?","choices":null,"answer":"-7","why":"For the first, 4 + 2m + 6 = 0 gives m = −5. For the second, 12 − 10 + n = 0 gives n = −2. Their sum is −7.","math":"x^2+mx+6,\\quad3x^2-5x+n","figure":null,"id":"lesson-13-q6","equations":["assets/lesson-13-q6-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"The polynomial x² − 10x + c has a repeated real root. What is c?","choices":null,"answer":"25","why":"A repeated root requires completing the square with no remainder: x² − 10x + 25 = (x − 5)². Equivalently, the discriminant 100 − 4c is zero.","math":null,"figure":null,"id":"lesson-13-q7","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"}]},{"id":"lesson-14","title":"Desmos Theory","day":7,"section":0,"url":"https://www.loom.com/share/5f71f27b93fa4f1dad11537eeec5c84e","embed":"https://www.loom.com/embed/5f71f27b93fa4f1dad11537eeec5c84e","questions":[{"stem":"For the function below, what is f(17) − f(−5)?","choices":null,"answer":"0","why":"Both inputs are 11 units from 6, so |17 − 6| = |−5 − 6|. Every corresponding term matches; the difference is zero for all a and b.","math":"f(x)=a|x-6|^2+b|x-6|+9","figure":null,"id":"lesson-14-q1","equations":["assets/lesson-14-q1-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"For the function below, what is h(−1) + h(9)?","choices":null,"answer":"14","why":"The shifted inputs are −5 and 5. Their cubes and first powers cancel in the sum, leaving 7 + 7 = 14.","math":"h(x)=p(x-4)^3+q(x-4)+7","figure":null,"id":"lesson-14-q2","equations":["assets/lesson-14-q2-0.png"],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Constants a and b satisfy a > b > 5. Which pair is permitted for testing a conjecture?","choices":["a = 5, b = 4","a = 7, b = 7","a = 6.5, b = 6","a = 0, b = 0"],"answer":"C","why":"6.5 > 6 > 5 satisfies every strict inequality. Constants need not be integers unless the problem requires integers.","math":null,"figure":null,"id":"lesson-14-q3","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Which statement must be true for all positive x and y satisfying xy = 12?","choices":["x + y = 7","x²y² = 144","x = 3","x/y = 3/4"],"answer":"B","why":"Squaring xy = 12 gives x²y² = 144. A particular permitted pair, such as (3, 4), cannot justify the other statements for every pair.","math":null,"figure":null,"id":"lesson-14-q4","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"If f(x) = a(x − 2)² + c and f(7) = 31, what is f(−3)?","choices":null,"answer":"31","why":"The inputs 7 and −3 are each 5 units from the axis x = 2. The squared terms are equal, so the function values are equal.","math":null,"figure":null,"id":"lesson-14-q5","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"A student tests a = 1 and finds a proposed identity holds. Which conclusion is justified?","choices":["The identity is proved.","The identity holds for this tested value; more reasoning is needed for all allowed values.","The identity cannot fail for any integer.","The identity holds only at a = 1."],"answer":"B","why":"A successful test is evidence about the chosen input, not a proof for all values. Algebraic reasoning can establish an invariant; a valid counterexample can disprove one.","math":null,"figure":null,"id":"lesson-14-q6","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"},{"stem":"Positive x and y satisfy 2x + y = 11. What is 4ˣ·2ʸ?","choices":null,"answer":"2048","why":"Rewrite 4ˣ as 2²ˣ. The product is 2^(2x + y) = 2¹¹ = 2,048. This uses the entire given constraint instead of guessing individual values.","math":null,"figure":null,"id":"lesson-14-q7","equations":[],"difficulty":"Hard","hardFocus":"Multi-step reasoning with distractors based on common SAT errors"}]},{"id":"lesson-15","title":"Identifying Independent Clauses","day":8,"section":1,"url":"https://www.loom.com/share/5ca7a3f0dfe045f398ef80bf1c3c7886","embed":"https://www.loom.com/embed/5ca7a3f0dfe045f398ef80bf1c3c7886","questions":[{"stem":"Which option is a complete independent clause?","choices":["Although the telescope recorded a faint signal","Recording a faint signal from a distant star","The telescope recorded a faint signal","To record a faint signal from a distant star"],"answer":"C","why":"The telescope is the subject and recorded is a finite predicate. Although makes A dependent; B and D lack a finite predicate.","math":null,"figure":null,"id":"lesson-15-q1","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The collection of letters from the expedition ______.” Which choice makes a complete sentence?","choices":["revealing an unexpected friendship","to reveal an unexpected friendship","which revealed an unexpected friendship","reveals an unexpected friendship"],"answer":"D","why":"The sentence needs a finite predicate for collection. Reveals provides it; the other options create modifiers or infinitive phrases.","math":null,"figure":null,"id":"lesson-15-q2","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"Which word is the finite main verb? “Determining whether the fragments belonged to the same vessel required careful analysis.”","choices":["Determining","belonged","required","analysis"],"answer":"C","why":"The gerund phrase beginning Determining is the subject. Required is its finite predicate. Belonged is inside the embedded whether clause.","math":null,"figure":null,"id":"lesson-15-q3","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"Which option is a complete independent clause?","choices":["That the seedlings survived the drought surprised the researchers","Because the seedlings survived the drought","The seedlings surviving the drought","Which seedlings survived the drought"],"answer":"A","why":"The nominal that-clause is the subject of surprised. A sentence beginning with that can be complete; the outer syntax matters.","math":null,"figure":null,"id":"lesson-15-q4","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The researchers, comparing photographs taken decades apart, ______.” Which choice makes a complete sentence?","choices":["documenting a decline in ice cover","documented a decline in ice cover","who documented a decline in ice cover","to document a decline in ice cover"],"answer":"B","why":"The comparing phrase is a modifier. Documented supplies the finite predicate needed by researchers.","math":null,"figure":null,"id":"lesson-15-q5","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"Which statement about this sentence is correct? “The archivist is organizing the papers and cataloging the photographs.”","choices":["It is incomplete because both action words end in −ing.","It is complete because is forms a finite verb phrase with the coordinated participles.","It needs a comma before and.","It has no subject."],"answer":"B","why":"Is organizing and cataloging is a finite coordinated verb phrase. An −ing form can be part of a complete predicate with an auxiliary.","math":null,"figure":null,"id":"lesson-15-q6","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“Near the entrance to the underground chamber ______.” Which choice makes a complete sentence?","choices":["a series of carved symbols","standing several stone pillars","stand several stone pillars","which several stone pillars surround"],"answer":"C","why":"An inverted clause follows the location phrase: stand is the finite verb and several stone pillars is the subject.","math":null,"figure":null,"id":"lesson-15-q7","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"}]},{"id":"lesson-16","title":"Punctuation — First Half","day":9,"section":1,"url":"https://www.loom.com/share/b45fbd1a70df45aab5b68fa668bf2da0","embed":"https://www.loom.com/embed/b45fbd1a70df45aab5b68fa668bf2da0","questions":[{"stem":"“The dye initially appeared brown ______ under ultraviolet light, it glowed bright green.” Which choice conforms to Standard English conventions?","choices":[", however,","; however,"," however;",", however;"],"answer":"B","why":"The two independent clauses are The dye initially appeared brown and under ultraviolet light, it glowed bright green. Use a semicolon between them and a comma after however.","math":null,"figure":null,"id":"lesson-16-q1","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The experiment required three materials ______ a glass tube, a rubber stopper, and distilled water.” Which choice fills the blank?","choices":[":",",",";","no punctuation"],"answer":"A","why":"The complete clause introduces an explanatory list, so a colon is appropriate.","math":null,"figure":null,"id":"lesson-16-q2","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The materials required for the experiment included ______ a glass tube, a rubber stopper, and distilled water.” Which choice fills the blank?","choices":[":",";","—","no punctuation"],"answer":"D","why":"Included directly introduces its objects. A boundary would separate the verb from its objects; the words before the blank are not a complete clause.","math":null,"figure":null,"id":"lesson-16-q3","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The ridge—barely visible from the valley ______ provided a route to the summit.” Which choice fills the blank?","choices":[",",";","—",":"],"answer":"C","why":"A matching dash closes the parenthetical interruption. The underlying clause is The ridge provided a route.","math":null,"figure":null,"id":"lesson-16-q4","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The researchers sampled ponds in Dover, Delaware ______ Salem, Oregon ______ and Erie, Pennsylvania.” Which punctuation fills both blanks?","choices":["commas","semicolons","colons","periods"],"answer":"B","why":"Each list item contains a comma separating city and state. Semicolons clarify the boundaries between complex items.","math":null,"figure":null,"id":"lesson-16-q5","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The samples were stored in sealed containers ______ and the labels were checked twice.” Which choice fills the blank?","choices":[",",";","no punctuation",":"],"answer":"A","why":"Two independent clauses are joined by and. A comma before the coordinating conjunction separates them.","math":null,"figure":null,"id":"lesson-16-q6","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The samples were stored in sealed containers and ______ checked twice before shipment.” Which choice fills the blank?","choices":[";",",","—","no punctuation"],"answer":"D","why":"Stored and checked are coordinated predicate parts with the same subject. Do not separate them with a clause boundary.","math":null,"figure":null,"id":"lesson-16-q7","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The museum acquired the painting ______ that depicts the harbor at dawn.” Which choice fills the blank?","choices":[",",";","no punctuation",":"],"answer":"C","why":"The restrictive that-clause identifies which painting was acquired and stays integrated with its noun.","math":null,"figure":null,"id":"lesson-16-q8","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The historian asked whether the map had been altered ______” Which choice fills the blank?","choices":["?",".",";",","],"answer":"B","why":"The sentence reports an indirect question. It is a statement and ends with a period.","math":null,"figure":null,"id":"lesson-16-q9","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The manuscript was unsigned ______ its handwriting matched that of the poet.” Which choice fills the blank?","choices":[",",";","no punctuation","and;"],"answer":"B","why":"Both sides are independent clauses. A semicolon is valid. A comma alone creates a comma splice; no punctuation creates a run-on.","math":null,"figure":null,"id":"lesson-16-q10","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"}]},{"id":"lesson-17","title":"Verb Questions","day":10,"section":1,"url":"https://www.youtube.com/watch?v=-qK1rXOFFVI","embed":"https://www.youtube.com/embed/-qK1rXOFFVI?autoplay=0&mute=1","questions":[{"stem":"“The arrangement of mirrors and lenses ______ light onto a small sensor.” Which choice fills the blank?","choices":["direct","directs","have directed","are directing"],"answer":"B","why":"The singular head arrangement determines agreement. The plural objects in the of-phrase do not change the subject.","math":null,"figure":null,"id":"lesson-17-q1","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“Along the edge of the marsh ______ several unusually tall reeds.” Which choice fills the blank?","choices":["grows","has grown","grow","is growing"],"answer":"C","why":"The subject follows the verb: several unusually tall reeds is plural. The location phrase is not the subject.","math":null,"figure":null,"id":"lesson-17-q2","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“Each of the devices ______ a different wavelength.” Which choice fills the blank?","choices":["measure","measures","are measuring","have measured"],"answer":"B","why":"Each is singular, regardless of the plural devices in the prepositional phrase.","math":null,"figure":null,"id":"lesson-17-q3","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The lead investigator, as well as two assistants, ______ the results every morning.” Which choice fills the blank?","choices":["review","reviews","have reviewed","are reviewing"],"answer":"B","why":"As well as two assistants does not form a compound subject joined by and. Investigator requires reviews.","math":null,"figure":null,"id":"lesson-17-q4","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The engineer and the designer ______ a shared workspace.” Which choice fills the blank?","choices":["uses","is using","use","has used"],"answer":"C","why":"Two people joined by and form a plural subject.","math":null,"figure":null,"id":"lesson-17-q5","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“By the time the expedition reached the summit in 1936, the team ______ three supply camps.” Which choice fills the blank?","choices":["will establish","had established","establishes","has established"],"answer":"B","why":"The camps were established before a specified event in the past. Past perfect expresses the earlier action.","math":null,"figure":null,"id":"lesson-17-q6","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The instrument, ______ in a protective case, remained undamaged during transport.” Which choice fills the blank?","choices":["packed","packs","is packing","has packed"],"answer":"A","why":"Packed in a protective case is a passive participial modifier enclosed by commas. Remained is the main finite verb.","math":null,"figure":null,"id":"lesson-17-q7","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The botanists ______ the seedlings under constant light observed a change in leaf color.” Which choice fills the blank?","choices":["grew","are growing","growing","have grown"],"answer":"C","why":"Growing the seedlings under constant light modifies botanists. Observed is the main finite predicate.","math":null,"figure":null,"id":"lesson-17-q8","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The program was designed to classify images, detect unusual patterns, and ______ the findings.” Which choice fills the blank?","choices":["report","reporting","reported","reports"],"answer":"A","why":"The coordinated infinitives share to: to classify, detect, and report. Match the parallel verb form.","math":null,"figure":null,"id":"lesson-17-q9","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“A series of measurements collected during the storm ______ that the pressure had fallen rapidly.” Which choice fills the blank?","choices":["indicate","indicates","have indicated","are indicating"],"answer":"B","why":"The head series is singular. Collected during the storm modifies measurements.","math":null,"figure":null,"id":"lesson-17-q10","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"}]},{"id":"lesson-18","title":"Must Know SAT Grammar Patterns","day":10,"section":1,"url":"https://www.youtube.com/watch?v=hSCNS0PJnZg","embed":"https://www.youtube.com/embed/hSCNS0PJnZg?autoplay=0&mute=1","questions":[{"stem":"“The satellite adjusted ______ position after detecting a small change in orbit.” Which choice fills the blank?","choices":["its","it’s","their","they’re"],"answer":"A","why":"The singular satellite takes possessive its. It’s means it is.","math":null,"figure":null,"id":"lesson-18-q1","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The two lenses differ in shape, but ______ optical properties are similar.” Which choice fills the blank?","choices":["its","it’s","their","they’re"],"answer":"C","why":"The antecedent two lenses is plural, and a possessive is needed.","math":null,"figure":null,"id":"lesson-18-q2","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The three ______ proposals were reviewed separately; each researcher had submitted one.” Which choice fills the blank?","choices":["researcher’s","researchers’","researchers","researcher"],"answer":"B","why":"Three researchers form a plural possessive. Put the apostrophe after the plural s.","math":null,"figure":null,"id":"lesson-18-q3","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The ______ outer shell protects the delicate circuitry.” The text refers to one device. Which choice fills the blank?","choices":["devices","devices’","device’s","device"],"answer":"C","why":"The shell belongs to one device: use the singular possessive device’s.","math":null,"figure":null,"id":"lesson-18-q4","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“After examining the fossil under a microscope, ______.” Which choice completes the sentence correctly?","choices":["a narrow groove was discovered by the scientist","the scientist discovered a narrow groove","a narrow groove became visible","the microscope revealed a narrow groove"],"answer":"B","why":"The modifier describes the person examining the fossil. The scientist must be the subject that immediately follows.","math":null,"figure":null,"id":"lesson-18-q5","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“Published in 1958, ______.” Which choice completes the sentence correctly?","choices":["the author’s debut novel attracted wide attention","the author attracted attention with a debut novel","readers admired the author’s debut novel","critics praised the debut novel’s author"],"answer":"A","why":"The thing published was the novel. In A, the subject head is novel, despite the possessive author’s.","math":null,"figure":null,"id":"lesson-18-q6","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“Known for its unusually thick bark, ______ protects itself against frequent fires.” Which choice fills the blank?","choices":["the tree’s adaptation","the thick outer layer","the tree","the researchers’ favorite specimen’s bark"],"answer":"C","why":"The modifier describes the tree. The main clause also needs the tree as the entity protecting itself.","math":null,"figure":null,"id":"lesson-18-q7","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"}]},{"id":"lesson-19","title":"Solving Grammar Demonstration","day":11,"section":1,"url":"https://www.loom.com/share/4d9478b97c3941dc9168277444e97c69","embed":"https://www.loom.com/embed/4d9478b97c3941dc9168277444e97c69","questions":[{"stem":"“The machine’s design—an arrangement of gears developed over several years ______ allowed it to operate with little vibration.” Which choice fills the blank?","choices":["—",",",";",":"],"answer":"A","why":"A paired dash closes the parenthetical phrase. The underlying clause is The machine’s design allowed it to operate.","math":null,"figure":null,"id":"lesson-19-q1","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The notes from the final rehearsal ______ several changes to the lighting plan.” Which choice fills the blank?","choices":["documents","document","is documenting","has documented"],"answer":"B","why":"Notes is plural; from the final rehearsal is a modifier.","math":null,"figure":null,"id":"lesson-19-q2","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“A researcher hoping to distinguish the two minerals ______ a test based on fluorescence.” Which choice fills the blank?","choices":["devising","to devise","devised","who devised"],"answer":"C","why":"The subject needs a finite predicate. Hoping to distinguish the two minerals is only a modifier.","math":null,"figure":null,"id":"lesson-19-q3","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The new sensor has one notable advantage ______ it detects motion without requiring visible light.” Which choice fills the blank?","choices":[",",":","no punctuation","and;"],"answer":"B","why":"The complete first clause introduces an explanation of the advantage. Use a colon.","math":null,"figure":null,"id":"lesson-19-q4","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“Designed to withstand strong ocean currents, ______.” Which choice completes the sentence correctly?","choices":["engineers tested the new turbine for months","the new turbine underwent months of testing","months of testing evaluated the new turbine","the engineers’ test lasted several months"],"answer":"B","why":"The turbine was designed to withstand the currents, so it must be the subject following the modifier.","math":null,"figure":null,"id":"lesson-19-q5","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The researchers compared the two minerals and measured ______ densities.” Which choice fills the blank?","choices":["its","it’s","their","they’re"],"answer":"C","why":"The densities belong to two minerals. Their is the plural possessive.","math":null,"figure":null,"id":"lesson-19-q6","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The archive contains maps of Quito, Ecuador ______ La Paz, Bolivia ______ and Lima, Peru.” Which punctuation fills both blanks?","choices":["commas","semicolons","colons","dashes"],"answer":"B","why":"Semicolons separate complex list items containing internal commas.","math":null,"figure":null,"id":"lesson-19-q7","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“By 2010, the observatory ______ nearly a decade of measurements, which researchers analyzed the following year.” Which choice fills the blank?","choices":["will accumulate","has accumulated","had accumulated","accumulates"],"answer":"C","why":"Accumulation occurred before a later past event; use past perfect.","math":null,"figure":null,"id":"lesson-19-q8","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The team knew that the initial result was promising ______ further trials were still necessary.” Which choice fills the blank?","choices":[", however,","; however,"," however;",", however;"],"answer":"B","why":"The independent clauses need a valid boundary: semicolon, then however followed by a comma.","math":null,"figure":null,"id":"lesson-19-q9","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"},{"stem":"“The curator discussed whether the restored instrument could still be played ______” Which choice fills the blank?","choices":["?",".",":",";"],"answer":"B","why":"An indirect question is embedded in a declarative sentence. End the sentence with a period.","math":null,"figure":null,"id":"lesson-19-q10","equations":[],"difficulty":"Hard","hardFocus":"Competing sentence-level constraints and precise evidence-based choices"}]},{"id":"lesson-20","title":"Problem Solving & Data Analysis","day":12,"section":2,"url":"https://www.youtube.com/watch?v=rytygT3oFO4","embed":"https://www.youtube.com/embed/rytygT3oFO4?autoplay=0&mute=1","questions":[{"stem":"The table shows the lengths of 10 seedlings. What is their mean length, in centimeters?","choices":null,"answer":"14.4","why":"Use the frequencies as weights: (10·2 + 14·5 + 18·3)/10 = 144/10 = 14.4. Averaging the three listed lengths without their frequencies would be incorrect.","math":null,"figure":{"type":"table","headers":["Length (cm)","Frequency"],"rows":[[10,2],[14,5],[18,3]]},"id":"lesson-20-q1","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"Data set A is 4, 6, 8, 10, 12. Data set B is formed by adding 30 to every value in A. Which statement is true?","choices":["The mean and standard deviation both increase by 30.","The mean increases by 30, and the standard deviation is unchanged.","The mean is unchanged, and the standard deviation increases by 30.","The mean and standard deviation are unchanged."],"answer":"B","why":"Translation increases every center measure by 30 but preserves all distances from the mean. Therefore standard deviation and range are unchanged.","math":null,"figure":null,"id":"lesson-20-q2","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"The values 2, 5, 7, 8, and 13 form a data set. The value 25 is added. By how much does the median increase?","choices":null,"answer":"0.5","why":"The original median is 7. The new ordered set has six values, so its median is (7 + 8)/2 = 7.5. Adding a high outlier can change the median; calculate rather than assume.","math":null,"figure":null,"id":"lesson-20-q3","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"The table gives temperatures of two liquids. Between which pair of consecutive times is the magnitude of Liquid A’s average cooling rate smaller than that of Liquid B?","choices":["0 to 10 minutes","10 to 20 minutes","20 to 30 minutes","The magnitudes are equal in every interval."],"answer":"C","why":"Over the first two intervals A drops 20 and 12 degrees, whereas B drops 10 and 8. Over the last interval A drops 4 and B drops 6, so A’s rate magnitude is smaller then. A lower temperature alone would not determine its cooling rate.","math":null,"figure":{"type":"table","headers":["Time (min)","A (°C)","B (°C)"],"rows":[[0,80,80],[10,60,70],[20,48,62],[30,44,56]]},"id":"lesson-20-q4","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"A square panel has area 4,500 square centimeters. What is its area in square meters? (1 meter = 100 centimeters.)","choices":null,"answer":"0.45","why":"Square the linear conversion: 1 m² = 10,000 cm². Therefore 4,500/10,000 = 0.45 m². Dividing by 100 would convert a length, not an area.","math":null,"figure":null,"id":"lesson-20-q5","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"After a 20% discount and a 5% tax on the discounted price, a desk costs $252. What was the original price, in dollars?","choices":null,"answer":"300","why":"Let P be the original price. P(0.80)(1.05) = 252, so P = 252/0.84 = 300. The percentage factors multiply; they do not simply cancel.","math":null,"figure":null,"id":"lesson-20-q6","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"A 12-liter solution contains 25% salt by volume. Pure water is added until the concentration is 15%. How many liters of water were added?","choices":null,"answer":"8","why":"Salt remains 12(0.25) = 3 liters. If w liters of water are added, 3/(12 + w) = 0.15. Hence the total is 20 liters and w = 8.","math":null,"figure":null,"id":"lesson-20-q7","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"One person is chosen at random from participants who completed a workshop. What is the probability that the person is in Group B?","choices":["18/70","18/30","18/42","30/70"],"answer":"C","why":"Restrict the population to completers: 24 + 18 = 42 people. Of those, 18 are in B. The total group size and entire participant count are not the correct denominator.","math":null,"figure":{"type":"table","headers":["Group","Completed","Did not complete"],"rows":[["A",24,16],["B",18,12]]},"id":"lesson-20-q8","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"A random sample of 400 members of one city’s public library system finds that 62% prefer digital notices. The margin of error is 4 percentage points. Which conclusion is supported?","choices":["Exactly 62% of all residents prefer digital notices.","A plausible range for the proportion of library-system members who prefer digital notices is 58% to 66%.","At least 96% of library-system members prefer digital notices.","The result applies to every library system in the country."],"answer":"B","why":"The interval is 62% ± 4 percentage points. Random sampling supports inference to the sampling population, library-system members, not all residents or the whole country.","math":null,"figure":null,"id":"lesson-20-q9","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"},{"stem":"Researchers recruit 120 volunteers and randomly assign half to a new study method and half to an existing method. Both groups study the same material for the same amount of time. Which feature most directly supports a causal conclusion about the methods?","choices":["The volunteers came from one school.","The groups were randomly assigned.","The study included 120 people rather than 12.","The study reported an average score."],"answer":"B","why":"Random assignment helps balance other influences between treatment groups and supports a causal comparison under a well-controlled design. It differs from random sampling, which supports population generalization.","math":null,"figure":null,"id":"lesson-20-q10","equations":[],"difficulty":"Hard","hardFocus":"Multi-step interpretation of tables, models, samples, and conditions"}]},{"id":"lesson-21","title":"Geometry & Trigonometry","day":13,"section":2,"url":"https://www.youtube.com/watch?v=u6LL3Pbo3HI","embed":"https://www.youtube.com/embed/u6LL3Pbo3HI?autoplay=0&mute=1","questions":[{"stem":"Lines ℓ and m are parallel. A transversal forms an angle of (3x + 8)° on ℓ and a same-side interior angle of (5x + 12)° on m. What is x?","choices":null,"answer":"20","why":"Same-side interior angles between parallel lines are supplementary: (3x + 8) + (5x + 12) = 180. Thus 8x = 160 and x = 20.","math":null,"figure":null,"id":"lesson-21-q1","equations":[],"difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"In right triangle ABC, angle C is 90° and sin A = 5/13. What is tan B?","choices":["5/13","5/12","12/13","12/5"],"answer":"D","why":"The sides opposite A, adjacent A, and the hypotenuse have ratio 5:12:13 by the Pythagorean theorem. For B, opposite is 12 and adjacent is 5, so tan B = 12/5. The ratio does not specify the actual lengths.","math":null,"figure":null,"id":"lesson-21-q2","equations":[],"difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"A right triangle has legs of length 9 and 12. What is the length of the altitude from its right angle to the hypotenuse?","choices":null,"answer":"7.2","why":"The hypotenuse is 15. Compute the area in two ways: (1/2)(9)(12) = (1/2)(15)h. Therefore h = 108/15 = 7.2.","math":null,"figure":{"type":"altitude"},"id":"lesson-21-q3","equations":[],"image":"assets/lesson-21-q3-figure.png","difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"Two similar solid containers have surface areas in the ratio 9:16. The smaller container has volume 81 cubic centimeters. What is the larger container’s volume?","choices":null,"answer":"192","why":"The length scale factor is √(16/9) = 4/3. The volume factor is (4/3)³ = 64/27. Multiply 81 by 64/27 to get 192.","math":null,"figure":null,"id":"lesson-21-q4","equations":[],"difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"A right square pyramid has base side length 10 and vertical height 12. What is its total surface area, including its base?","choices":null,"answer":"360","why":"The slant height of a triangular face is √(12² + 5²) = 13. Each face has area (1/2)(10)(13) = 65. Add four faces and the base: 4(65) + 100 = 360.","math":null,"figure":{"type":"pyramid"},"id":"lesson-21-q5","equations":[],"image":"assets/lesson-21-q5-figure.png","difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"A cylindrical tank has base area 60 square meters and height 4 meters. A solid object occupying 35 cubic meters is placed in it. The remaining space is filled with water. What volume of water is needed, in cubic meters?","choices":null,"answer":"205","why":"Tank volume = base area · height = 60·4 = 240. Subtract the solid object’s 35 to get 205.","math":null,"figure":null,"id":"lesson-21-q6","equations":[],"difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"A rectangle is inscribed in a circle of radius 13. One side of the rectangle has length 10. What is its area?","choices":null,"answer":"240","why":"Its diagonal is the circle’s diameter, 26. The other side is √(26² − 10²) = √576 = 24. Area = 10·24 = 240.","math":null,"figure":{"type":"rectangle_circle"},"id":"lesson-21-q7","equations":[],"image":"assets/lesson-21-q7-figure.png","difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"Triangles ABC and DEF have ∠A = ∠D = 40° and ∠B = ∠E = 65°. Which additional fact guarantees that they are congruent?","choices":["∠C = ∠F","AB = DE","AB = 2DE","AC/DF = 2"],"answer":"B","why":"The two equal angle pairs establish similarity. Equality of the corresponding included side AB and DE fixes the scale factor at 1 and gives ASA congruence. A adds no new information; C and D imply a different size.","math":null,"figure":null,"id":"lesson-21-q8","equations":[],"difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"A triangle has two sides of lengths 6 and 11. How many integer lengths are possible for its third side?","choices":null,"answer":"11","why":"The triangle inequality requires |11 − 6| < x < 11 + 6, or 5 < x < 17. The integers 6 through 16 give 11 possibilities. Both endpoints are excluded.","math":null,"figure":null,"id":"lesson-21-q9","equations":[],"difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"},{"stem":"Two tangents from point P touch a circle at A and B. The angle APB is 70°, and the circle has circumference 72. What is the length of the minor arc AB?","choices":null,"answer":"22","why":"Each radius is perpendicular to its tangent, so ∠AOB = 360 − 90 − 90 − 70 = 110°. The minor arc is (110/360)(72) = 22.","math":null,"figure":{"type":"tangents"},"id":"lesson-21-q10","equations":[],"image":"assets/lesson-21-q10-figure.png","difficulty":"Hard","hardFocus":"Linked angle, similarity, measurement, and diagram constraints"}]},{"id":"lesson-22","title":"Improve Your Reading Score Overnight","day":14,"section":3,"url":"https://www.youtube.com/watch?v=NBECQxDBQQs","embed":"https://www.youtube.com/embed/NBECQxDBQQs?autoplay=0&mute=1","questions":[{"stem":"A historian found that a port’s tax receipts rose sharply between 1710 and 1720. During the same period, the city lowered its tax rate on each shipment. The historian argues that the receipts provide evidence of expanding commerce rather than higher taxes on existing trade.\n\nWhich finding would most directly support the historian’s argument?","choices":["The number of shipments entering the port more than doubled during the period.","The city’s tax rate remained higher than that of a neighboring port.","Several merchants complained about the complexity of the tax forms.","Tax receipts from 1700 were smaller than those from 1705."],"answer":"A","why":"An increase in shipments directly supports expansion in trade volume and explains rising receipts despite a lower per-shipment rate. B compares cities, C addresses administration, and D concerns an earlier period.","math":null,"figure":null,"id":"lesson-22-q1","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"In a study of urban gardens, insect visits increased after gardeners planted additional native flowers. However, the increase occurred only in gardens that already had nesting habitat nearby. The researchers therefore caution that planting flowers alone may not produce the same result in every garden.\n\nWhich conclusion is most logically supported?","choices":["Native flowers discourage insects from nesting.","Nesting habitat may influence whether additional flowers attract more insect visits.","Every garden with nesting habitat will attract the same number of insects.","Non-native flowers are always more effective than native flowers."],"answer":"B","why":"The effect varied with nearby nesting habitat, suggesting habitat influences the response. The text does not establish harm, equal outcomes, or superiority of non-native flowers.","math":null,"figure":null,"id":"lesson-22-q2","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The library’s old catalog listed a manuscript as anonymous. A newly discovered letter identifies its author, but the letter was written fifty years after the manuscript and cites no source. Researchers have consequently treated the identification as a promising lead rather than a settled attribution.\n\nWhich choice best states the main idea?","choices":["The old catalog is certainly more accurate than the new letter.","Researchers consider the letter useful but insufficient to establish authorship.","The manuscript was written fifty years before the author was born.","Anonymous manuscripts cannot be attributed to specific authors."],"answer":"B","why":"The researchers neither reject the lead nor accept it as conclusive. A overstates the catalog’s reliability, C invents chronology, and D asserts an unsupported impossibility.","math":null,"figure":null,"id":"lesson-22-q3","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"Biologists measured the time required for two seed types to germinate under the same laboratory conditions. The results are shown in the table. A researcher claims that the treatment reduced germination time more for Type A than for Type B.\n\nWhich comparison most directly supports the claim?","choices":["Type A took 8 days with treatment, whereas Type B took 10.","Type A’s time fell by 6 days, whereas Type B’s time fell by 2.","Type A took 14 days without treatment, whereas Type B took 12.","Both types germinated more quickly with treatment."],"answer":"B","why":"Compare the change within each type, then compare those changes: A declines 14 − 8 = 6 days and B declines 12 − 10 = 2. A and C compare levels; D omits which reduction was larger.","math":null,"figure":{"type":"table","headers":["Seed type","Untreated (days)","Treated (days)"],"rows":[["A",14,8],["B",12,10]]},"id":"lesson-22-q4","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"Many early maps emphasized coastlines and major roads. One mapmaker instead carefully marked wells along a desert route. <u>Those wells were often separated by distances that travelers could cover in a single day.</u> This detail suggests that the map was designed partly to help people plan journeys rather than merely to record landforms.\n\nWhat is the function of the underlined sentence?","choices":["It presents evidence supporting an interpretation of the map’s practical purpose.","It explains why early maps never included roads.","It introduces a competing account that the text later rejects.","It shows that the mapmaker had measured every traveler’s walking speed."],"answer":"A","why":"The spacing of wells supports the interpretation that travelers could use the map to plan daily stages. B contradicts the opening, and C and D add claims not present.","math":null,"figure":null,"id":"lesson-22-q5","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The engineer’s initial model was deliberately <u>modest</u>: it aimed to predict whether a bridge component would fail, not the precise moment at which failure would occur. Later models addressed the timing question.\n\nAs used in the text, what does “modest” most nearly mean?","choices":["Unreliable","Limited in scope","Embarrassed","Inexpensive"],"answer":"B","why":"The contrast concerns how much the model attempted to predict, so modest means limited in scope. The text does not evaluate cost or reliability.","math":null,"figure":null,"id":"lesson-22-q6","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"Two species of coastal plants can survive salty water. In field surveys, Species X was found mainly on exposed beaches, while Species Y was found mainly in sheltered inlets. When grown under identical sheltered conditions, however, both species grew equally well. These results suggest that the field distribution of Species X ______.\n\nWhich choice most logically completes the text?","choices":["proves that it cannot survive in sheltered settings","may reflect factors other than an inability to grow in sheltered conditions","was caused entirely by differences in salt tolerance","will remain unchanged in every future survey"],"answer":"B","why":"Equal growth under sheltered conditions undercuts the claim that X cannot grow there. The data allow other explanations but do not establish one sole cause or a permanent distribution.","math":null,"figure":null,"id":"lesson-22-q7","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"}]},{"id":"lesson-23","title":"How to Solve Reading Comprehension Questions","day":15,"section":3,"url":"https://www.youtube.com/watch?v=dUl1Hmgx-NE","embed":"https://www.youtube.com/embed/dUl1Hmgx-NE?autoplay=0&mute=1","questions":[{"stem":"Researchers propose that an unfamiliar typeface improves recall only when readers have ample time to study a passage. They predict that, under a strict time limit, the effort needed to decode the typeface will offset any benefit.\n\nWhich finding would most directly support the full proposal?","choices":["With unlimited study time, readers using either typeface recalled some details.","Readers rated the unfamiliar typeface as harder to read.","Readers given ample time recalled more with the unfamiliar typeface, but readers under a strict limit showed no recall advantage from it.","Readers under a strict limit recalled fewer details than readers given ample time, regardless of typeface."],"answer":"C","why":"The claim includes both a typeface benefit under ample time and its absence under a strict limit. C tests both. A lacks the comparative advantage, B measures difficulty rather than recall, and D isolates time rather than the interaction.","math":null,"figure":null,"id":"lesson-23-q1","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"An economist argues that a transit discount produced a larger proportional increase in monthly trips among occasional riders than among frequent riders. The survey data below report average monthly trips before and after the discount.\n\nWhich statement most directly supports the argument?","choices":["Frequent riders made more trips than occasional riders after the discount.","Occasional riders’ trips increased by 100%, while frequent riders’ trips increased by 10%.","Both groups made more trips after the discount.","Frequent riders made 22 monthly trips after the discount."],"answer":"B","why":"The relative increase is 2/2 = 100% for occasional riders and 2/20 = 10% for frequent riders. B directly compares the effects. Absolute levels and a general increase do not establish which group responded more strongly.","math":null,"figure":{"type":"table","headers":["Group","Before","After"],"rows":[["Occasional",2,4],["Frequent",20,22]]},"id":"lesson-23-q2","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"A museum replaced several descriptive labels with questions intended to prompt discussion. Visitors in the redesigned room spent longer looking at the objects, but the study did not record their conversations or assess their understanding. Thus, while the redesign may have increased attention, the study ______.\n\nWhich choice most logically completes the text?","choices":["established that every visitor understood the objects better","could not determine whether the labels improved discussion or comprehension","showed that descriptive labels always discourage attention","demonstrated that visitors preferred questions to every other label format"],"answer":"B","why":"The recorded measure is viewing time. Discussion and comprehension were not measured, so the study cannot establish those outcomes. The other answers make unsupported universal or preference claims.","math":null,"figure":null,"id":"lesson-23-q3","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"Text 1: A scholar contends that a poet’s frequent use of unfinished sentences invites readers to supply connections that the poems leave unstated.\n\nText 2: Another scholar notes that, in the poet’s early drafts, many sentences were complete. The poet later removed connecting words, increasing the effort readers must make to follow the poems.\n\nHow would the scholar in Text 2 most likely respond to the claim in Text 1?","choices":["By suggesting that the drafts support the idea that the poet deliberately increased readers’ interpretive role","By arguing that unfinished sentences were accidental errors that the poet never corrected","By asserting that readers cannot understand any of the poems","By claiming that complete sentences require more interpretation than incomplete sentences"],"answer":"A","why":"The deliberate revisions removed explicit connections and increased reader effort, supporting the proposed interpretive role. B contradicts revision evidence; C and D go beyond or reverse the text.","math":null,"figure":null,"id":"lesson-23-q4","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"A paleontologist was <u>reserved</u> in discussing a newly discovered footprint. Although its shape resembled that of a known species, the surrounding rock had been distorted, making a confident identification difficult.\n\nAs used in the text, what does “reserved” most nearly mean?","choices":["Set aside for future use","Cautious in expressing a conclusion","Unwilling to share any evidence","Certain of an identification"],"answer":"B","why":"The rock distortion limits certainty, so reserved describes caution in speaking. A uses another meaning; C and D misrepresent the researcher’s response.","math":null,"figure":null,"id":"lesson-23-q5","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The conventional account places the settlement’s founding in the tenth century. <u>Charcoal recovered beneath its oldest stone building has recently been dated to the eighth century.</u> The charcoal does not prove that the stone building existed then, but it raises the possibility of earlier activity at the site.\n\nWhat is the function of the underlined sentence?","choices":["It offers new evidence that motivates a qualified challenge to the conventional chronology.","It proves that all buildings in the settlement were built in the eighth century.","It describes an error that the next sentence dismisses entirely.","It explains how charcoal dating was invented."],"answer":"A","why":"The date creates grounds to consider earlier activity, while the next sentence limits what can be inferred. B overstates, C ignores the retained possibility, and D is unrelated.","math":null,"figure":null,"id":"lesson-23-q6","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"Researchers hypothesize that a bird’s ability to locate hidden food depends more on landmarks than on smell.\n\nWhich experimental result would most directly weaken the hypothesis?","choices":["Removing nearby landmarks had little effect on success, but blocking access to odor cues sharply reduced success.","Birds found visible food more quickly than hidden food.","Birds usually approached the food from the same direction.","The food had a strong odor detectable by humans."],"answer":"A","why":"The result compares the effects of removing each cue and finds odor more influential, directly opposing the proposed relative importance. B and C do not compare cues; D alone does not show how birds use them.","math":null,"figure":null,"id":"lesson-23-q7","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"A historian studying household inventories found that ceramic plates appeared more often in wealthy households than in poorer ones. She cautions that inventories were compiled mainly for households with property to distribute and may underrepresent the poorest residents.\n\nWhich statement would the historian most likely agree with?","choices":["The inventories are useless for studying any household.","The observed difference may not fully describe the entire population.","Poor residents certainly owned more plates than wealthy residents.","All inventories were fabricated by wealthy residents."],"answer":"B","why":"The caution concerns sampling coverage and limits generalization. It does not eliminate all usefulness or establish an opposite pattern.","math":null,"figure":null,"id":"lesson-23-q8","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"In laboratory tests, a coating reduced corrosion on steel samples exposed to saltwater for thirty days. The researchers stress that the test duration was short compared with the years that bridge components remain in service.\n\nWhich finding would most directly address the researchers’ stated limitation?","choices":["The coating can be applied in three colors.","The coating also reduces corrosion during a multi-year saltwater exposure test.","Uncoated samples sometimes showed surface discoloration.","The laboratory used a calibrated measuring instrument."],"answer":"B","why":"The limitation is duration. A multi-year exposure test addresses whether the short-term effect persists. The other findings do not extend the test over the relevant period.","math":null,"figure":null,"id":"lesson-23-q9","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The graph shows annual publication counts for two fields. A researcher claims that Field A’s growth was sustained rather than confined to a single jump.\n\nWhich observation best supports this claim?","choices":["Field A had more publications than Field B in 2022.","Field A’s publication count increased in each successive interval shown.","Field B’s count was unchanged in the last interval.","The combined count was greatest in 2022."],"answer":"B","why":"The claim is about the pattern within Field A over time. Its counts rise 20 → 35 → 50 → 65 at every step. The alternatives compare levels, discuss B, or combine fields.","math":null,"figure":{"type":"line","x":[2016,2018,2020,2022],"series":{"Field A":[20,35,50,65],"Field B":[30,32,45,45]},"xlabel":"Year","ylabel":"Publications"},"id":"lesson-23-q10","equations":[],"image":"assets/lesson-23-q10-figure.png","difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"}]},{"id":"lesson-24","title":"Never Miss Another SAT Transition Question","day":16,"section":3,"url":"https://www.youtube.com/watch?v=BhDFdrPA368","embed":"https://www.youtube.com/embed/BhDFdrPA368?autoplay=0&mute=1","questions":[{"stem":"A new archive search revealed several letters from the composer’s early career. ______ none of the letters mentioned the unfinished symphony that researchers hoped to study.\n\nWhich transition best completes the text?","choices":["Similarly,","However,","For example,","Therefore,"],"answer":"B","why":"The discovery creates an expectation of useful evidence, but the letters lack the desired information. However signals this contrast.","math":null,"figure":null,"id":"lesson-24-q1","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"Some coastal organisms build structures that alter water flow. ______ oyster reefs can slow currents and trap sediment.\n\nWhich transition best completes the text?","choices":["For example,","Nevertheless,","In conclusion,","Instead,"],"answer":"A","why":"The oyster reef is a particular example of the general claim about organisms altering flow.","math":null,"figure":null,"id":"lesson-24-q2","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The new battery stores more energy than its predecessor. ______ it can be recharged in less time.\n\nWhich transition best completes the text?","choices":["On the contrary,","Even so,","Moreover,","As a result,"],"answer":"C","why":"The second sentence adds another advantage. It does not follow causally from greater energy storage.","math":null,"figure":null,"id":"lesson-24-q3","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The storm damaged the only road connecting the town to the coast. ______ deliveries had to be rerouted through the mountains.\n\nWhich transition best completes the text?","choices":["Consequently,","Likewise,","For instance,","To be sure,"],"answer":"A","why":"Road damage caused the rerouting, so use a cause-and-effect transition.","math":null,"figure":null,"id":"lesson-24-q4","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The technicians first cleaned the lens and checked its alignment. ______ they calibrated the sensor using a reference light source.\n\nWhich transition best completes the text?","choices":["In contrast,","Next,","In other words,","Regardless,"],"answer":"B","why":"The text describes successive steps in a procedure. Next marks the following step.","math":null,"figure":null,"id":"lesson-24-q5","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The manuscript’s provenance remains uncertain. ______ researchers have not established where it was produced or how it reached the collection.\n\nWhich transition best completes the text?","choices":["In other words,","By comparison,","Accordingly,","Meanwhile,"],"answer":"A","why":"The second sentence restates and explains what uncertain provenance means.","math":null,"figure":null,"id":"lesson-24-q6","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The observatory is far from major cities. ______ its remote location does not eliminate all artificial light: nearby industrial facilities remain brightly illuminated at night.\n\nWhich transition best completes the text?","choices":["As a result,","Nonetheless,","For example,","Similarly,"],"answer":"B","why":"The second sentence qualifies the expectation that remoteness eliminates light pollution. Nonetheless expresses that contrast.","math":null,"figure":null,"id":"lesson-24-q7","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"During the trial, the instrument returned to the same baseline reading after each disturbance. ______ the reading stabilized at 18 units, despite repeated changes to the temperature.\n\nWhich transition best completes the text?","choices":["Increasingly,","Again and again,","By contrast,","Eventually,"],"answer":"B","why":"The result repeatedly recurred, rather than becoming larger or occurring only once after a delay.","math":null,"figure":null,"id":"lesson-24-q8","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The report claims that the entire community adopted the new irrigation method immediately. ______ records show that only a few farms tried it during the first season.\n\nWhich transition best completes the text?","choices":["In fact,","Similarly,","As a consequence,","For this reason,"],"answer":"A","why":"In fact introduces evidence correcting the preceding claim. The records contradict immediate universal adoption rather than add a similar case or an effect.","math":null,"figure":null,"id":"lesson-24-q9","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"},{"stem":"The team expected the inscription to be damaged after centuries outdoors. ______ some weathering was visible, but most of the characters remained legible.\n\nWhich transition best completes the text?","choices":["Of course,","Instead,","Therefore,","For example,"],"answer":"A","why":"Some weathering confirms a reasonable expectation; the rest of the sentence qualifies its extent. Instead would falsely suggest that weathering replaced expected damage as a contrasting event.","math":null,"figure":null,"id":"lesson-24-q10","equations":[],"difficulty":"Hard","hardFocus":"Two-step evidence, inference, and function-of-sentence reasoning"}]}],"days":[{"title":"Desmos Mastery • Day 1","pdf":"01_Desmos_Day_1.pdf","lessons":["lesson-1","lesson-2"]},{"title":"Desmos Mastery • Day 2","pdf":"02_Desmos_Day_2.pdf","lessons":["lesson-3","lesson-4","lesson-5"]},{"title":"Desmos Mastery • Day 3","pdf":"03_Desmos_Day_3.pdf","lessons":["lesson-6","lesson-7"]},{"title":"Desmos Mastery • Day 4","pdf":"04_Desmos_Day_4.pdf","lessons":["lesson-8","lesson-9"]},{"title":"Desmos Mastery • Day 5","pdf":"05_Desmos_Day_5.pdf","lessons":["lesson-10"]},{"title":"Desmos Mastery • Day 6","pdf":"06_Desmos_Day_6.pdf","lessons":["lesson-11"]},{"title":"Desmos Mastery • Day 7","pdf":"07_Desmos_Day_7.pdf","lessons":["lesson-12","lesson-13"]},{"title":"Desmos Mastery • Day 8","pdf":"08_Desmos_Day_8.pdf","lessons":["lesson-14"]},{"title":"Grammar Mastery • Day 1","pdf":"09_Grammar_Day_1.pdf","lessons":["lesson-15"]},{"title":"Grammar Mastery • Day 2","pdf":"10_Grammar_Day_2.pdf","lessons":["lesson-16"]},{"title":"Grammar Mastery • Day 3","pdf":"11_Grammar_Day_3.pdf","lessons":["lesson-17","lesson-18"]},{"title":"Grammar Mastery • Day 4","pdf":"12_Grammar_Day_4.pdf","lessons":["lesson-19"]},{"title":"Non-Desmos • Problem Solving & Data Analysis","pdf":"13_Non_Desmos_Data_Analysis.pdf","lessons":["lesson-20"]},{"title":"Non-Desmos • Geometry & Trigonometry","pdf":"14_Non_Desmos_Geometry.pdf","lessons":["lesson-21"]},{"title":"Reading • Improve Your Reading Score Overnight","pdf":"15_Reading_Overnight.pdf","lessons":["lesson-22"]},{"title":"Reading • How to Solve Reading Comprehension Questions","pdf":"16_Reading_Comprehension.pdf","lessons":["lesson-23"]},{"title":"Reading • Never Miss Another SAT Transition Question","pdf":"17_Reading_Transitions.pdf","lessons":["lesson-24"]}]};
